-- ====================================================================
-- SejarahWira  |  ERA 10: Malaysia dan Dunia  |  seed_era10.sql
-- 3 naratif (6 + 6 + 6 babak = 18 babak), setiap babak ada 1 quest, serta 50 soalan.
--
-- SETIAP naratif merangkumi enam topik yang sama: (1) pertubuhan serantau, (2) pertubuhan antarabangsa, (3) ASEAN,
-- (4) Komanwel dan OIC, (5) PBB dan pengiktirafan PBB, (6) pengiktirafan UNESCO. Naratif hanya berbeza pada peranan, suara,
-- watak sampingan dan jenis cabaran.
--
-- Pelajar MERASUK jasad watak rekaan (peranan naratif):
--   Naratif 1 (Sidang Serantau Wakil Muda ASEAN)           = Wakil Muda ASEAN (NPC 221)
--   Naratif 2 (Rondaan Keamanan Penjaga Topi Biru)         = Penjaga Keamanan PBB (NPC 222)
--   Naratif 3 (Lawatan Pameran Malaysia dan Dunia)         = Pemandu Pameran UNESCO (NPC 223)
-- Baris dialog tanpa penutur (npcID NULL) ialah baris "Pemain" / "kau" yang dituturkan tokoh peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran,
--   3 = pengenalan peranan oleh Pendekar Bayang.
-- Setiap quest ada "aftermath" (Akibat jika salah), pilihan salah jenis 3/5 ada "consequence",
-- dan satu "Giliran Anda" (turns). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Jalankan SELEPAS seed.sql (NPC 221-231 dibuat di sini):
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era10.sql
-- Selamat dijalankan berulang kali (kandungan Era 10 lama dipadam dahulu). Era lain tidak disentuh.
--
-- NOTA: kandungan mengikut bahan asal sahaja; tiada fakta tambahan dimasukkan.
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 10 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 10;

-- 2. NPC baharu Era 10 (nama fail gambar mengikut folder npc sebenar).
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (1 Susun Garis Masa, 2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 10 (50 soalan aneka pilihan, ID 1001-1050)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 10;


COMMIT;