INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(221, 'Wakil Muda ASEAN', 'Wakil muda yang menghadiri sidang serantau dengan fail penuh nota (watak rekaan).', 'Menyampaikan kisah pertubuhan serantau dan sumbangan Malaysia.', 'wakil_asean.png'),
(222, 'Penjaga Keamanan PBB', 'Anggota pasukan pengaman yang bertugas dengan topi biru (watak rekaan).', 'Menyampaikan kisah sumbangan Malaysia kepada PBB dan pertubuhan dunia.', 'penjaga_keamanan_pbb.png'),
(223, 'Pemandu Pameran UNESCO', 'Pemandu pameran yang menjaga bilik warisan dunia (watak rekaan).', 'Menyampaikan kisah warisan Malaysia yang diiktiraf dunia.', 'ahli_antropologi_UNESCO.png'),
(224, 'Pakar Ekonomi ASEAN', 'Pakar yang menjelaskan matlamat dan kerjasama ASEAN (watak rekaan).', 'Menerangkan matlamat dan sumbangan Malaysia dalam ASEAN.', 'pakar_ekonomi_asean.png'),
(225, 'Wakil PBB', 'Wakil yang berucap di dewan sidang PBB (watak rekaan).', 'Menerangkan latar PBB dan sumbangan Malaysia.', 'wakil_pbb(un).png'),
(226, 'Utusan Komanwel', 'Utusan yang membawa berita daripada pertubuhan Komanwel (watak rekaan).', 'Menerangkan latar Komanwel dan sumbangan Malaysia.', 'utusan_komanwel.png'),
(227, 'Wakil OIC', 'Wakil yang menghadiri persidangan negara Islam (watak rekaan).', 'Menerangkan latar OIC dan sumbangan Malaysia.', 'wakil_oic.png'),
(228, 'Duta NAM', 'Duta yang mewakili negara-negara berkecuali (watak rekaan).', 'Menerangkan Pergerakan Negara-negara Berkecuali.', 'duta_nam.png'),
(229, 'Sukarelawan Kemanusiaan OIC', 'Sukarelawan yang membantu mangsa konflik (watak rekaan).', 'Menceritakan sumbangan Malaysia dalam OIC.', 'sukarelawan_kemanusiaan_OIC.png'),
(230, 'Tunku Abdul Rahman', 'Dilantik sebagai Setiausaha Agung pertama OIC.', 'Setiausaha Agung pertama OIC.', 'tunku_abdul_rahman.png'),
(231, 'Wakil Indonesia', 'Wakil yang menyambut tetamu di ibu pejabat ASEAN di Jakarta (watak rekaan).', 'Menyambut tetamu sidang serantau.', 'wakil_indonesia.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(1001, 'Sidang Serantau Wakil Muda ASEAN', 10, 'Masuki peranan wakil muda ASEAN yang menghadiri sidang di bilik mesyuarat dunia. Dalam sidang itu kau mengenali pertubuhan serantau dan antarabangsa, sumbangan Malaysia dalam ASEAN, Komanwel, OIC dan PBB, serta pengiktirafan UNESCO.'),
(1002, 'Rondaan Keamanan Penjaga Topi Biru', 10, 'Masuki peranan penjaga keamanan PBB yang meronda dari bilik mesyuarat ke bilik mesyuarat. Dalam rondaanmu kau mengenali pertubuhan serantau dan antarabangsa, sumbangan Malaysia dalam ASEAN, Komanwel, OIC dan PBB, serta pengiktirafan UNESCO.'),
(1003, 'Lawatan Pameran Malaysia dan Dunia', 10, 'Masuki peranan pemandu pameran UNESCO yang membawa pelawat melawat bilik demi bilik. Dalam lawatan itu kau mengenali pertubuhan serantau dan antarabangsa, sumbangan Malaysia dalam ASEAN, Komanwel, OIC dan PBB, serta pengiktirafan UNESCO.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e10_n1_s1', 'Bilik sidang serantau berkaca besar dengan bendera negara Asia Tenggara berbaris dan meja peta dunia bercahaya di tengah. Kau, wakil muda ASEAN, menyusun fail sementara pakar ekonomi dan wakil Indonesia menyambutmu.', 1, 1001, 'malaysia_dan_dunia_serantau.png'),
('e10_n1_s2', 'Bilik mesyuarat dunia dengan meja bulat besar dan peta dunia bercahaya di dinding. Kau, wakil muda ASEAN, duduk di meja sementara utusan Komanwel, wakil PBB, wakil OIC dan duta NAM masuk satu persatu.', 2, 1001, 'bilik_mesyuarat_dunia.png'),
('e10_n1_s3', 'Bilik mesyuarat panjang dengan bendera meja negara anggota ASEAN dan peta Asia Tenggara di dinding. Kau, wakil muda ASEAN, menyemak dokumen sementara pakar ekonomi menerangkan sumbangan Malaysia.', 3, 1001, 'bilik_mesyuarat.png'),
('e10_n1_s4', 'Bilik mesyuarat London yang megah dengan jambatan Thames di tingkap dan peta serantau di meja panjang. Kau, wakil muda ASEAN, duduk bersama utusan Komanwel, wakil OIC dan Tunku Abdul Rahman.', 4, 1001, 'bilik_mesyuarat_london.png'),
('e10_n1_s5', 'Dewan sidang besar PBB dengan bendera Malaysia di pentas dan skrin kawalan menunjukkan peta dunia. Kau, wakil muda ASEAN, berdiri di tengah bersama wakil PBB dan penjaga keamanan PBB.', 5, 1001, 'malaysia_di_pentas_dunia.png'),
('e10_n1_s6', 'Ruang pameran UNESCO dengan kotak kaca silinder memaparkan gunung, gua dan peta warisan. Kau, wakil muda ASEAN, melangkah masuk sementara pemandu pameran menyambutmu dengan lampu pameran yang bersinar.', 6, 1001, 'ruang_unesco.png'),
('e10_n2_s1', 'Bilik mesyuarat moden dengan peta Asia Tenggara di dinding dan meja berkilat. Kau, penjaga keamanan PBB, berdiri di muka pintu sementara pakar ekonomi dan wakil Indonesia bersiap untuk sidang serantau.', 1, 1002, 'bilik_mesyuarat_modern.png'),
('e10_n2_s2', 'Bilik mesyuarat dunia dengan meja bulat dan peta dunia bercahaya. Kau, penjaga keamanan PBB, meronda di sekeliling meja sementara utusan Komanwel, wakil PBB, wakil OIC dan duta NAM menunggu giliran.', 2, 1002, 'bilik_mesyuarat_dunia.png'),
('e10_n2_s3', 'Bilik mesyuarat panjang dengan bendera meja negara ASEAN dan peta Asia Tenggara di dinding. Kau, penjaga keamanan PBB, memeriksa bilik sementara pakar ekonomi menerangkan ASEAN.', 3, 1002, 'bilik_mesyuarat.png'),
('e10_n2_s4', 'Bilik mesyuarat formal berhias ukiran Islam dengan meja panjang dan dokumen bertulis tangan. Kau, penjaga keamanan PBB, mengiringi utusan Komanwel dan wakil OIC masuk ke bilik itu.', 4, 1002, 'bilik_mesyuarat_formal.png'),
('e10_n2_s5', 'Pusat operasi PBB yang sibuk dengan kotak bantuan bertanda PBB, mesin telex dan anggota topi biru. Kau, penjaga keamanan PBB, menyemak laporan sementara wakil PBB menerangkan sumbangan Malaysia.', 5, 1002, 'bilik_UNMM.png'),
('e10_n2_s6', 'Ruang pameran UNESCO dengan kotak kaca silinder memaparkan gunung, gua dan peta warisan. Kau, penjaga keamanan PBB, mengiringi pemandu pameran menyusuri kotak kaca itu pada akhir rondaan.', 6, 1002, 'ruang_unesco.png'),
('e10_n3_s1', 'Bilik pameran serantau dengan bendera negara Asia Tenggara dan meja peta dunia bercahaya di tengah. Kau, pemandu pameran, membuka lawatan bersama pakar ekonomi dan wakil Indonesia.', 1, 1003, 'malaysia_dan_dunia_serantau.png'),
('e10_n3_s2', 'Bilik mesyuarat dunia dengan meja bulat dan peta dunia bercahaya di dinding. Kau, pemandu pameran, membawa pelawat bertemu utusan Komanwel, wakil PBB, wakil OIC dan duta NAM.', 2, 1003, 'bilik_mesyuarat_dunia.png'),
('e10_n3_s3', 'Bilik mesyuarat moden dengan peta Asia Tenggara di dinding dan meja panjang berkilat. Kau, pemandu pameran, membawa pelawat mengenali ASEAN bersama pakar ekonomi.', 3, 1003, 'bilik_mesyuarat_modern.png'),
('e10_n3_s4', 'Bilik mesyuarat London yang megah dengan peta serantau di meja panjang. Kau, pemandu pameran, membawa pelawat bertemu utusan Komanwel, wakil OIC dan Tunku Abdul Rahman.', 4, 1003, 'bilik_mesyuarat_london.png'),
('e10_n3_s5', 'Dewan sidang besar PBB dengan bendera Malaysia di pentas dan skrin kawalan menunjukkan peta dunia. Kau, pemandu pameran, membawa pelawat berdiri di tengah bersama wakil PBB dan penjaga keamanan PBB.', 5, 1003, 'malaysia_di_pentas_dunia.png'),
('e10_n3_s6', 'Ruang pameran UNESCO dengan kotak kaca silinder memaparkan gunung, gua dan peta warisan. Kau, pemandu pameran, membawa pelawat ke bilik terakhir bersama ahli antropologi UNESCO.', 6, 1003, 'ruang_unesco.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(1001, 'e10_n1_s1', 'Padanan Nama Pertubuhan Serantau', 'Padankan nama penuh pertubuhan serantau dengan singkatannya.', '4', 'Mengenal pasti pertubuhan serantau SEAFET, ASA dan ASEAN.', '{"pairs": [{"text": "Southeast Asia Friendship and Economic Treaty", "pair": 1}, {"text": "SEAFET", "pair": 1}, {"text": "Association of Southeast Asia", "pair": 2}, {"text": "ASA", "pair": 2}, {"text": "Association of Southeast Asian Nations", "pair": 3}, {"text": "ASEAN", "pair": 3}], "aftermath": "Nama pertubuhan serantau tersalah padan. Dokumen sidang dicetak dengan singkatan yang tidak tepat.", "turns": [{"after": 6, "options": [{"text": "ASEAN.", "isCorrect": true, "reaction": "Tepat, wakil muda! Wakil Indonesia mengangguk dan bendera di belakangnya berkibar."}, {"text": "SEAFET.", "isCorrect": false, "reaction": "SEAFET hanya tiga negara, wakil muda! Wakil Indonesia ketawa sambil menggeleng."}, {"text": "ASA.", "isCorrect": false, "reaction": "ASA juga tiga negara sahaja, wakil muda! Wakil Indonesia tersenyum sambil membetulkan."}], "clue": "Pertubuhan itu melibatkan lima negara."}]}'),
(1002, 'e10_n1_s2', 'Susun Garis Masa Penubuhan Pertubuhan', 'Susun penubuhan pertubuhan mengikut urutan tahun.', '1', 'Mengenal pasti pertubuhan serantau dan antarabangsa.', '{"timelineItems": [{"id": 1, "year": "1931", "text": "Komanwel dibentuk pada 11 Disember", "why": "Tahun paling awal dalam senarai."}, {"id": 2, "year": "1945", "text": "PBB ditubuhkan pada 24 Oktober", "why": "Datang selepas Komanwel."}, {"id": 3, "year": "1967", "text": "ASEAN ditubuhkan pada 8 Ogos", "why": "Datang selepas PBB."}, {"id": 4, "year": "1969", "text": "OIC ditubuhkan pada 25 September", "why": "Tahun paling akhir dalam senarai."}], "aftermath": "Garis masa pertubuhan tersalah susun. Delegasi menyangka OIC lebih tua daripada Komanwel.", "turns": [{"after": 6, "options": [{"text": "57 buah negara.", "isCorrect": true, "reaction": "Tepat, wakil muda! Wakil OIC mengangkat kedua-dua tangan tanda bangga."}, {"text": "120 buah negara.", "isCorrect": false, "reaction": "Itu bilangan NAM, wakil muda! Wakil OIC tersenyum sambil menunjuk ke arah duta NAM."}, {"text": "54 buah negara.", "isCorrect": false, "reaction": "Itu bilangan Komanwel, wakil muda! Wakil OIC ketawa kecil."}], "clue": "Bilangannya lebih daripada lima puluh."}]}'),
(1003, 'e10_n1_s3', 'Nyahkod Dokumen Penubuhan ASEAN', 'Baca dokumen ASEAN yang luntur dan tentukan bandar ibu pejabat yang tidak kelihatan.', '5', 'Mengenal pasti latar belakang, matlamat dan sumbangan Malaysia dalam ASEAN.', '{"clueText": "Dokumen menulis: ASEAN ditubuhkan pada 8 Ogos 1967 dan dianggotai 10 negara Asia Tenggara. Nama bandar ibu pejabatnya sudah luntur dan tidak kelihatan.", "options": [{"text": "Jakarta, Indonesia.", "isCorrect": true}, {"text": "Bangkok, Thailand.", "isCorrect": false, "consequence": "Dokumen ditulis semula dengan ibu pejabat yang tersalah. Delegasi menyangka ibu pejabat ASEAN di Bangkok."}, {"text": "Manila, Filipina.", "isCorrect": false, "consequence": "Dokumen ditulis semula dengan ibu pejabat yang tersalah. Delegasi menyangka ibu pejabat ASEAN di Manila."}], "aftermath": "Ibu pejabat ASEAN ditulis tidak tepat. Delegasi tersalah arah ke bandar lain.", "turns": [{"after": 6, "options": [{"text": "Zon Aman, Bebas dan Berkecuali.", "isCorrect": true, "reaction": "Tepat, wakil muda! Pakar ekonomi menepuk meja tanda setuju."}, {"text": "Zon Aman, Bebas dan Bersenjata.", "isCorrect": false, "reaction": "Terbalik maksudnya, wakil muda! Pakar ekonomi menggeleng sambil ketawa."}, {"text": "Zon Aman, Bersatu dan Berkuasa.", "isCorrect": false, "reaction": "Bukan itu, wakil muda! Pakar ekonomi mengangkat kening."}], "clue": "Ia bermaksud aman, bebas dan tidak memihak."}]}'),
(1004, 'e10_n1_s4', 'Penjelasan Komanwel dan OIC', 'Pilih pernyataan yang betul tentang Komanwel dan OIC untuk delegasi.', '3', 'Mengenal pasti latar belakang dan sumbangan Malaysia dalam Komanwel dan OIC.', '{"prompt": "Seorang delegasi bertanya kepadamu: yang manakah pernyataan yang betul tentang Komanwel dan OIC?", "options": [{"text": "Komanwel berpusat di London dan Malaysia menjadi tuan rumah CHOGM 1989; OIC berpusat di Jeddah dan Tunku Setiausaha Agung pertamanya.", "isCorrect": true}, {"text": "Komanwel berpusat di Jeddah dan Malaysia menjadi tuan rumah CHOGM 1989; OIC berpusat di London dan Tunku Setiausaha Agung pertamanya.", "isCorrect": false, "consequence": "Delegasi mencatat ibu pejabat yang bertukar tempat. Dia menyangka Komanwel berpusat di Jeddah."}, {"text": "Komanwel berpusat di London dan Malaysia menjadi tuan rumah CHOGM 1974; OIC berpusat di Jeddah dan Tunku Setiausaha Agung pertamanya.", "isCorrect": false, "consequence": "Delegasi mencatat tahun CHOGM yang salah. Dia menyangka CHOGM dianjurkan pada tahun persidangan OIC 1974."}], "aftermath": "Maklumat Komanwel dan OIC dicatat dengan tidak tepat. Delegasi pulang membawa ibu pejabat dan tahun yang salah.", "turns": [{"after": 6, "options": [{"text": "Universiti Islam Antarabangsa Malaysia (UIAM).", "isCorrect": true, "reaction": "Tepat, wakil muda! Wakil OIC mengangguk puas."}, {"text": "Universiti Kebangsaan Malaysia (UKM) di Bangi.", "isCorrect": false, "reaction": "Bukan itu, wakil muda! Wakil OIC tersenyum sambil menggeleng."}, {"text": "Universiti Putra Malaysia (UPM) di Serdang.", "isCorrect": false, "reaction": "Bukan itu, wakil muda! Wakil OIC mengangkat kening."}], "clue": "Namanya mengandungi perkataan Islam dan antarabangsa."}]}'),
(1005, 'e10_n1_s5', 'Cari Bukti Sumbangan Malaysia di PBB', 'Cari bukti sumbangan dan pengiktirafan Malaysia di dewan sidang PBB.', '2', 'Mengenal pasti sumbangan Malaysia kepada PBB dan pengiktirafan PBB kepada Malaysia.', '{"bgImage": "../assets/gameAsset/background/malaysia_di_pentas_dunia.png", "hotspots": [{"name": "Dewan sidang: keahlian PBB terbuka kepada semua negara", "top": "42%", "left": "20%"}, {"name": "Bendera Malaysia: negara anggota PBB yang aktif menyumbang", "top": "24%", "left": "29%"}, {"name": "Peta dunia di skrin: pasukan pengaman PBB termasuk Malaysia", "top": "22%", "left": "88%"}, {"name": "Peta di skrin utama: kawasan tugas pasukan pengaman PBB", "top": "68%", "left": "49%"}], "aftermath": "Bukti sumbangan Malaysia tersalah cari. Wakil PBB menolak laporan yang tidak lengkap.", "turns": [{"after": 6, "options": [{"text": "Sijil dan pingat perkhidmatan PBB.", "isCorrect": true, "reaction": "Tepat, wakil muda! Penjaga keamanan memberi tabik hormat."}, {"text": "Wang tunai untuk setiap anggota.", "isCorrect": false, "reaction": "Bukan itu, wakil muda! Penjaga keamanan ketawa sambil menggeleng."}, {"text": "Kerusi tetap di dewan sidang.", "isCorrect": false, "reaction": "Bukan itu, wakil muda! Penjaga keamanan tersenyum sambil menunjuk ke arah pingat di dadanya."}], "clue": "Pengiktirafan itu boleh dipakai di dada."}]}'),
(1006, 'e10_n1_s6', 'Penerangan Warisan Dunia UNESCO', 'Pilih pernyataan yang betul tentang Tapak Warisan Dunia UNESCO di Malaysia.', '3', 'Mengenal pasti pengiktirafan UNESCO kepada Malaysia.', '{"prompt": "Seorang pelawat bertanya kepadamu: yang manakah pernyataan yang betul tentang Tapak Warisan Dunia UNESCO di Malaysia?", "options": [{"text": "Mulu dan Kinabalu diiktiraf pada 2000, Melaka dan George Town pada 2008, dan Lembah Lenggong pada 2012.", "isCorrect": true}, {"text": "Mulu dan Kinabalu diiktiraf pada 2008, Melaka dan George Town pada 2000, dan Lembah Lenggong pada 2012.", "isCorrect": false, "consequence": "Pelawat menulis tahun yang bertukar tempat. Dia menyangka Melaka diiktiraf lebih awal daripada Mulu."}, {"text": "Mulu dan Kinabalu diiktiraf pada 2000, Melaka dan George Town pada 2012, dan Lembah Lenggong pada 2008.", "isCorrect": false, "consequence": "Pelawat menulis tahun yang bertukar tempat. Dia menyangka Lenggong diiktiraf lebih awal daripada Melaka."}], "aftermath": "Tahun pengiktirafan UNESCO dicatat tidak tepat. Pelawat membawa pulang urutan yang salah.", "turns": [{"after": 6, "options": [{"text": "Silat diiktiraf pada tahun 2019.", "isCorrect": true, "reaction": "Tepat, wakil muda! Pemandu pameran mengangguk bangga."}, {"text": "Silat diiktiraf pada tahun 2005.", "isCorrect": false, "reaction": "Itu tahun Makyung, wakil muda! Pemandu pameran tersenyum sambil membetulkan."}, {"text": "Silat diiktiraf pada tahun 2020.", "isCorrect": false, "reaction": "Itu tahun Wangkang, wakil muda! Pemandu pameran ketawa kecil."}], "clue": "Tahun itu sebelum tahun 2020."}]}'),
(1007, 'e10_n2_s1', 'Kuiz Sidang Serantau', 'Pilih pernyataan yang betul tentang SEAFET, ASA dan ASEAN untuk wakil sidang.', '3', 'Mengenal pasti pertubuhan serantau SEAFET, ASA dan ASEAN.', '{"prompt": "Seorang wakil bertanya kepadamu: yang manakah pernyataan yang betul tentang SEAFET, ASA dan ASEAN?", "options": [{"text": "SEAFET dan ASA dianggotai Tanah Melayu, Thailand dan Filipina; ASEAN dianggotai lima negara termasuk Indonesia dan Singapura.", "isCorrect": true}, {"text": "SEAFET dan ASA dianggotai Tanah Melayu, Indonesia dan Singapura; ASEAN dianggotai tiga negara termasuk Thailand dan Filipina.", "isCorrect": false, "consequence": "Wakil itu mencatat anggota yang bertukar tempat. Dia menyangka Indonesia dan Singapura anggota SEAFET."}, {"text": "SEAFET dan ASA dianggotai Tanah Melayu, Thailand dan Filipina; ASEAN dianggotai tiga negara termasuk Indonesia dan Singapura.", "isCorrect": false, "consequence": "Wakil itu mencatat bilangan anggota ASEAN yang salah. Dia menyangka ASEAN hanya tiga negara."}], "aftermath": "Anggota pertubuhan serantau dicatat tidak tepat. Wakil membawa nota yang salah ke sidang.", "turns": [{"after": 5, "options": [{"text": "Association of Southeast Asia.", "isCorrect": true, "reaction": "Tepat, penjaga! Pakar ekonomi mengangkat ibu jari."}, {"text": "Alliance of Southeast Asian States.", "isCorrect": false, "reaction": "Hampir, penjaga! Pakar ekonomi ketawa sambil membetulkan perkataan pertama."}, {"text": "Association of South Asian Allies.", "isCorrect": false, "reaction": "Bukan itu, penjaga! Pakar ekonomi menggeleng sambil tersenyum."}], "clue": "Huruf pertama ASA ialah Association."}]}'),
(1008, 'e10_n2_s2', 'Padanan Pertubuhan Antarabangsa', 'Padankan setiap pertubuhan antarabangsa dengan keahliannya.', '4', 'Mengenal pasti pertubuhan antarabangsa Komanwel, PBB, OIC dan NAM.', '{"pairs": [{"text": "Komanwel", "pair": 1}, {"text": "Bekas tanah jajahan British", "pair": 1}, {"text": "PBB", "pair": 2}, {"text": "Terbuka kepada semua negara", "pair": 2}, {"text": "OIC", "pair": 3}, {"text": "57 buah negara Islam", "pair": 3}, {"text": "NAM", "pair": 4}, {"text": "120 buah negara membangun", "pair": 4}], "aftermath": "Keahlian pertubuhan antarabangsa tersalah padan. Pintu bilik mesyuarat tertukar tempat.", "turns": [{"after": 6, "options": [{"text": "PBB.", "isCorrect": true, "reaction": "Tepat, penjaga! Wakil PBB menghadiahkan tabik hormat."}, {"text": "Komanwel.", "isCorrect": false, "reaction": "Komanwel dibentuk pada tahun 1931, penjaga! Wakil PBB tersenyum sambil membetulkan."}, {"text": "OIC.", "isCorrect": false, "reaction": "OIC ditubuhkan pada tahun 1969, penjaga! Wakil PBB ketawa kecil."}], "clue": "Ia ditubuhkan selepas tahun 1931 dan sebelum tahun 1967."}]}'),
(1009, 'e10_n2_s3', 'Cari Bukti di Bilik ASEAN', 'Cari bukti maklumat ASEAN dan sumbangan Malaysia di bilik mesyuarat ini.', '2', 'Mengenal pasti latar belakang, matlamat dan sumbangan Malaysia dalam ASEAN.', '{"bgImage": "../assets/gameAsset/background/bilik_mesyuarat.png", "hotspots": [{"name": "Bendera Malaysia: tuan rumah Mesyuarat Menteri Luar ASEAN", "top": "46%", "left": "5%"}, {"name": "Peta Asia Tenggara: ASEAN dianggotai 10 negara Asia Tenggara", "top": "17%", "left": "27%"}, {"name": "Bendera Singapura: salah satu negara awal ASEAN", "top": "48%", "left": "70%"}, {"name": "Dokumen perjanjian: matlamat keamanan dan kestabilan politik", "top": "80%", "left": "25%"}], "aftermath": "Bukti ASEAN tersalah cari. Penjaga melaporkan bilik yang tidak lengkap.", "turns": [{"after": 5, "options": [{"text": "10 negara.", "isCorrect": true, "reaction": "Tepat, penjaga! Pakar ekonomi mengira sepuluh bendera di meja."}, {"text": "5 negara.", "isCorrect": false, "reaction": "Itu bilangan pengasas awal, penjaga! Pakar ekonomi tersenyum sambil menunjuk bendera lain."}, {"text": "57 negara.", "isCorrect": false, "reaction": "Itu bilangan OIC, penjaga! Pakar ekonomi ketawa kecil."}], "clue": "Bilangannya tepat sepuluh."}]}'),
(1010, 'e10_n2_s4', 'Nyahkod Catatan OIC', 'Baca catatan OIC yang luntur dan tentukan bandar ibu pejabat yang tidak kelihatan.', '5', 'Mengenal pasti latar belakang dan sumbangan Malaysia dalam Komanwel dan OIC.', '{"clueText": "Catatan menulis: OIC ditubuhkan pada 25 September 1969 dan dianggotai 57 negara Islam. Nama bandar ibu pejabatnya sudah luntur dan tidak kelihatan.", "options": [{"text": "Jeddah, Arab Saudi.", "isCorrect": true}, {"text": "London, England.", "isCorrect": false, "consequence": "Catatan ditulis semula dengan ibu pejabat yang tersalah. Penjaga menyangka ibu pejabat OIC di London."}, {"text": "New York, Amerika Syarikat.", "isCorrect": false, "consequence": "Catatan ditulis semula dengan ibu pejabat yang tersalah. Penjaga menyangka ibu pejabat OIC di New York."}], "aftermath": "Ibu pejabat OIC ditulis tidak tepat. Penjaga menghantar utusan ke bandar yang salah.", "turns": [{"after": 6, "options": [{"text": "Tunku Abdul Rahman.", "isCorrect": true, "reaction": "Tepat, penjaga! Sukarelawan itu memberi tabik hormat kepada Tunku."}, {"text": "Tun Abdul Razak.", "isCorrect": false, "reaction": "Bukan itu, penjaga! Sukarelawan itu tersenyum sambil menunjuk ke arah Tunku."}, {"text": "Tun Hussein Onn.", "isCorrect": false, "reaction": "Bukan itu, penjaga! Sukarelawan itu ketawa kecil."}], "clue": "Beliau juga Perdana Menteri pertama Malaysia."}]}'),
(1011, 'e10_n2_s5', 'Kuiz Pusat Operasi PBB', 'Pilih pernyataan yang betul tentang PBB dan sumbangan Malaysia.', '3', 'Mengenal pasti sumbangan Malaysia kepada PBB dan pengiktirafan PBB kepada Malaysia.', '{"prompt": "Seorang rekrut bertanya kepadamu: yang manakah pernyataan yang betul tentang PBB dan sumbangan Malaysia?", "options": [{"text": "PBB berpusat di New York; pasukan pengaman Malaysia diiktiraf melalui sijil dan pingat perkhidmatan PBB.", "isCorrect": true}, {"text": "PBB berpusat di London; pasukan pengaman Malaysia diiktiraf melalui sijil dan pingat perkhidmatan PBB.", "isCorrect": false, "consequence": "Rekrut itu menulis ibu pejabat PBB yang salah. Dia menyangka PBB berpusat di London."}, {"text": "PBB berpusat di New York; pasukan pengaman Malaysia diiktiraf melalui wang tunai dan kerusi tetap PBB.", "isCorrect": false, "consequence": "Rekrut itu menulis pengiktirafan yang salah. Dia menyangka pasukan pengaman menerima wang tunai."}], "aftermath": "Maklumat PBB dan pengiktirafan dicatat tidak tepat. Rekrut membawa pulang nota yang salah.", "turns": [{"after": 6, "options": [{"text": "Datuk Dr. Mazlan Othman.", "isCorrect": true, "reaction": "Tepat, penjaga! Wakil PBB mendongak ke langit sambil tersenyum."}, {"text": "Tan Sri Razali Ismail.", "isCorrect": false, "reaction": "Beliau Pengerusi Majlis Keselamatan, penjaga! Wakil PBB menggeleng sambil tersenyum."}, {"text": "Tunku Abdul Rahman.", "isCorrect": false, "reaction": "Beliau Setiausaha Agung OIC, penjaga! Wakil PBB ketawa kecil."}], "clue": "Beliau seorang wanita yang berkhidmat dalam bidang angkasa lepas."}]}'),
(1012, 'e10_n2_s6', 'Susun Garis Masa Pengiktirafan UNESCO', 'Susun pengiktirafan UNESCO kepada Malaysia mengikut urutan tahun.', '1', 'Mengenal pasti pengiktirafan UNESCO kepada Malaysia.', '{"timelineItems": [{"id": 1, "year": "2000", "text": "Taman Negara Gunung Mulu dan Taman Kinabalu menjadi Tapak Warisan Dunia", "why": "Tahun paling awal dalam senarai."}, {"id": 2, "year": "2005", "text": "Makyung diiktiraf sebagai Warisan Budaya Tidak Ketara", "why": "Datang selepas tapak alam semula jadi."}, {"id": 3, "year": "2008", "text": "Melaka dan George Town menjadi Tapak Warisan Dunia", "why": "Datang selepas Makyung."}, {"id": 4, "year": "2012", "text": "Warisan Arkeologi Lembah Lenggong menjadi Tapak Warisan Dunia", "why": "Datang selepas Melaka dan George Town."}, {"id": 5, "year": "2019", "text": "Silat diiktiraf sebagai Warisan Budaya Tidak Ketara", "why": "Tahun paling akhir dalam senarai."}], "aftermath": "Garis masa pengiktirafan UNESCO tersalah susun. Pemandu pameran menunda lampu kotak kaca.", "turns": [{"after": 7, "options": [{"text": "Tahun 2009.", "isCorrect": true, "reaction": "Tepat, penjaga! Pemandu pameran menyalakan lampu kotak kaca."}, {"text": "Tahun 2001.", "isCorrect": false, "reaction": "Itu tahun Hikayat Hang Tuah, penjaga! Pemandu pameran tersenyum sambil membetulkan."}, {"text": "Tahun 2018.", "isCorrect": false, "reaction": "Itu tahun Dondang Sayang, penjaga! Pemandu pameran ketawa kecil."}], "clue": "Tahun itu sebelum tahun 2010."}]}'),
(1013, 'e10_n3_s1', 'Nyahkod Papan Nama Anggota SEAFET', 'Baca papan nama yang luntur dan tentukan negara anggota SEAFET yang tidak kelihatan.', '5', 'Mengenal pasti pertubuhan serantau SEAFET, ASA dan ASEAN.', '{"clueText": "Papan menulis: SEAFET dan ASA dianggotai Tanah Melayu, Thailand dan satu negara lagi. Nama negara itu sudah luntur dan tidak kelihatan.", "options": [{"text": "Filipina.", "isCorrect": true}, {"text": "Indonesia.", "isCorrect": false, "consequence": "Papan ditulis semula dengan negara yang tersalah. Pelawat menyangka Indonesia anggota SEAFET."}, {"text": "Singapura.", "isCorrect": false, "consequence": "Papan ditulis semula dengan negara yang tersalah. Pelawat menyangka Singapura anggota SEAFET."}], "aftermath": "Anggota SEAFET ditulis tidak tepat. Pelawat membawa pulang catatan yang salah.", "turns": [{"after": 6, "options": [{"text": "Association of Southeast Asian Nations.", "isCorrect": true, "reaction": "Tepat, pemandu! Wakil Indonesia menepuk tangan."}, {"text": "Alliance of Southeast Asian National States.", "isCorrect": false, "reaction": "Hampir, pemandu! Wakil Indonesia ketawa sambil membetulkan."}, {"text": "Association of Southeast Asia Navies.", "isCorrect": false, "reaction": "Bukan itu, pemandu! Wakil Indonesia menggeleng sambil tersenyum."}], "clue": "Perkataan terakhirnya ialah Nations."}]}'),
(1014, 'e10_n3_s2', 'Penerangan Pertubuhan Antarabangsa', 'Pilih pernyataan yang betul tentang Komanwel, PBB, OIC dan NAM untuk pelawat.', '3', 'Mengenal pasti pertubuhan antarabangsa Komanwel, PBB, OIC dan NAM.', '{"prompt": "Seorang pelawat bertanya kepadamu: yang manakah pernyataan yang betul tentang Komanwel, PBB, OIC dan NAM?", "options": [{"text": "Komanwel: bekas jajahan British; PBB: semua negara; OIC: 57 negara Islam; NAM: 120 negara membangun.", "isCorrect": true}, {"text": "Komanwel: bekas jajahan British; PBB: semua negara; OIC: 120 negara Islam; NAM: 57 negara membangun.", "isCorrect": false, "consequence": "Pelawat menulis bilangan OIC dan NAM yang bertukar tempat. Dia menyangka OIC 120 negara."}, {"text": "Komanwel: semua negara; PBB: bekas jajahan British; OIC: 57 negara Islam; NAM: 120 negara membangun.", "isCorrect": false, "consequence": "Pelawat menulis keahlian Komanwel dan PBB yang bertukar tempat. Dia menyangka PBB hanya untuk bekas jajahan British."}], "aftermath": "Keahlian pertubuhan antarabangsa dicatat tidak tepat. Pelawat membawa pulang nota yang salah.", "turns": [{"after": 6, "options": [{"text": "120 buah negara.", "isCorrect": true, "reaction": "Tepat, pemandu! Duta NAM mengangkat ibu jari."}, {"text": "57 buah negara.", "isCorrect": false, "reaction": "Itu bilangan OIC, pemandu! Duta NAM tersenyum sambil menunjuk ke arah wakil OIC."}, {"text": "54 buah negara.", "isCorrect": false, "reaction": "Itu bilangan Komanwel, pemandu! Duta NAM ketawa kecil."}], "clue": "Bilangannya lebih daripada seratus."}]}'),
(1015, 'e10_n3_s3', 'Padanan Kad Pameran ASEAN', 'Padankan setiap butiran ASEAN dengan jawapannya.', '4', 'Mengenal pasti latar belakang, matlamat dan sumbangan Malaysia dalam ASEAN.', '{"pairs": [{"text": "Tarikh penubuhan ASEAN", "pair": 1}, {"text": "8 Ogos 1967", "pair": 1}, {"text": "Ibu pejabat ASEAN", "pair": 2}, {"text": "Jakarta, Indonesia", "pair": 2}, {"text": "Bilangan anggota ASEAN", "pair": 3}, {"text": "10 negara Asia Tenggara", "pair": 3}, {"text": "Dikemukakan oleh Malaysia", "pair": 4}, {"text": "ZOPFAN", "pair": 4}, {"text": "Disertai oleh Malaysia", "pair": 5}, {"text": "SEAMEO", "pair": 5}], "aftermath": "Kad pameran ASEAN tersalah padan. Pelawat menyalin butiran yang salah.", "turns": [{"after": 5, "options": [{"text": "Zon Aman, Bebas dan Berkecuali.", "isCorrect": true, "reaction": "Tepat, pemandu! Pakar ekonomi menepuk tangan."}, {"text": "Zon Aman, Bebas dan Bersenjata.", "isCorrect": false, "reaction": "Terbalik maksudnya, pemandu! Pakar ekonomi menggeleng sambil ketawa."}, {"text": "Zon Aman, Bersatu dan Berkuasa.", "isCorrect": false, "reaction": "Bukan itu, pemandu! Pakar ekonomi mengangkat kening."}], "clue": "Ia bermaksud aman, bebas dan tidak memihak."}]}'),
(1016, 'e10_n3_s4', 'Susun Garis Masa Sumbangan Malaysia dalam OIC dan Komanwel', 'Susun peristiwa OIC dan Komanwel yang melibatkan Malaysia mengikut urutan tahun.', '1', 'Mengenal pasti latar belakang dan sumbangan Malaysia dalam Komanwel dan OIC.', '{"timelineItems": [{"id": 1, "year": "1969", "text": "OIC ditubuhkan dan Tunku Abdul Rahman menjadi Setiausaha Agung pertama", "why": "Tahun paling awal dalam senarai."}, {"id": 2, "year": "1974", "text": "Malaysia menjadi tuan rumah Persidangan OIC buat kali pertama", "why": "Datang selepas penubuhan OIC."}, {"id": 3, "year": "1983", "text": "UIAM ditubuhkan", "why": "Datang selepas persidangan pertama."}, {"id": 4, "year": "1989", "text": "Malaysia menjadi tuan rumah CHOGM dan mengisytiharkan Deklarasi Langkawi", "why": "Datang selepas penubuhan UIAM."}, {"id": 5, "year": "1991", "text": "Malaysia menangani isu Bosnia dan Herzegovina dalam OIC", "why": "Datang selepas CHOGM."}, {"id": 6, "year": "2003", "text": "Malaysia menjadi tuan rumah Persidangan OIC buat kali kedua", "why": "Tahun paling akhir dalam senarai."}], "aftermath": "Garis masa sumbangan Malaysia tersalah susun. Pelawat menyangka UIAM lebih awal daripada persidangan OIC.", "turns": [{"after": 6, "options": [{"text": "Tunku Abdul Rahman.", "isCorrect": true, "reaction": "Tepat, pemandu! Wakil OIC memberi tabik hormat kepada Tunku."}, {"text": "Tun Abdul Razak.", "isCorrect": false, "reaction": "Bukan itu, pemandu! Wakil OIC tersenyum sambil menunjuk ke arah Tunku."}, {"text": "Tun Dr. Mahathir.", "isCorrect": false, "reaction": "Bukan itu, pemandu! Wakil OIC menggeleng sambil ketawa."}], "clue": "Beliau juga Perdana Menteri pertama Malaysia."}]}'),
(1017, 'e10_n3_s5', 'Nyahkod Sijil Pengerusi Majlis Keselamatan', 'Baca sijil yang luntur dan tentukan nama tokoh Malaysia yang tidak kelihatan.', '5', 'Mengenal pasti sumbangan Malaysia kepada PBB dan pengiktirafan PBB kepada Malaysia.', '{"clueText": "Sijil menulis: Pengerusi Majlis Keselamatan PBB (1989-1990) ialah tokoh Malaysia. Nama tokoh itu sudah luntur dan tidak kelihatan.", "options": [{"text": "Tan Sri Razali Ismail.", "isCorrect": true}, {"text": "Datuk Dr. Mazlan Othman.", "isCorrect": false, "consequence": "Sijil ditulis semula dengan nama yang tersalah. Pelawat menyangka Mazlan Othman Pengerusi Majlis Keselamatan."}, {"text": "Tunku Abdul Rahman.", "isCorrect": false, "consequence": "Sijil ditulis semula dengan nama yang tersalah. Pelawat menyangka Tunku Pengerusi Majlis Keselamatan PBB."}], "aftermath": "Nama tokoh pada sijil ditulis tidak tepat. Pelawat menyalin nama yang salah.", "turns": [{"after": 7, "options": [{"text": "Menyertai pasukan pengaman.", "isCorrect": true, "reaction": "Tepat, pemandu! Penjaga keamanan memberi tabik hormat."}, {"text": "Menghantar angkasawan ke angkasa.", "isCorrect": false, "reaction": "Bukan itu, pemandu! Penjaga keamanan ketawa sambil menunjuk ke arah topi birunya."}, {"text": "Menubuhkan sebuah bank dunia.", "isCorrect": false, "reaction": "Bukan itu, pemandu! Penjaga keamanan menggeleng sambil tersenyum."}], "clue": "Anggotanya memakai topi biru."}]}'),
(1018, 'e10_n3_s6', 'Cari Bukti Warisan Dunia', 'Cari bukti Tapak Warisan Dunia UNESCO di Malaysia pada kotak kaca pameran ini.', '2', 'Mengenal pasti pengiktirafan UNESCO kepada Malaysia.', '{"bgImage": "../assets/gameAsset/background/ruang_unesco.png", "hotspots": [{"name": "Gunung dalam kaca: Taman Kinabalu di Sabah, warisan alam 2000", "top": "50%", "left": "8%"}, {"name": "Gua batu kapur: Taman Negara Gunung Mulu di Sarawak, warisan 2000", "top": "52%", "left": "88%"}, {"name": "Peta bandar dalam kaca: Melaka dan George Town, warisan 2008", "top": "56%", "left": "72%"}, {"name": "Hologram tengah: Warisan Arkeologi Lembah Lenggong, 2012", "top": "42%", "left": "50%"}], "aftermath": "Bukti warisan dunia tersalah cari. Pelawat keluar dari pameran dengan maklumat yang salah.", "turns": [{"after": 7, "options": [{"text": "Sabah.", "isCorrect": true, "reaction": "Tepat, pemandu! Ahli antropologi menepuk bahumu."}, {"text": "Sarawak.", "isCorrect": false, "reaction": "Itu negeri Gunung Mulu, pemandu! Ahli antropologi tersenyum sambil membetulkan."}, {"text": "Pahang.", "isCorrect": false, "reaction": "Bukan itu, pemandu! Ahli antropologi ketawa kecil."}], "clue": "Gunung tertinggi Malaysia terletak di negeri itu."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e10_n1_s1', 'hint', 'SEAFET: Southeast Asia Friendship and Economic Treaty. ASA: Association of Southeast Asia. ASEAN: Association of Southeast Asian Nations (Malaysia, Indonesia, Thailand, Filipina, Singapura).', NULL, NULL),
(1001, NULL, 'hint', 'Tiga nama penuh: SEAFET, ASA dan ASEAN. Setiap satu ada singkatannya.', 'Pertubuhan serantau: SEAFET (Southeast Asia Friendship and Economic Treaty; Tanah Melayu, Thailand, Filipina), ASA (Association of Southeast Asia; Tanah Melayu, Thailand, Filipina) dan ASEAN (Association of Southeast Asian Nations; Malaysia, Indonesia, Thailand, Filipina, Singapura).', 'Betul! Tiga nama bertemu singkatannya dan bendera berkibar tanda hormat.'),
(NULL, 'e10_n1_s2', 'hint', 'Komanwel: bekas tanah jajahan British (1931). PBB: terbuka kepada semua negara (1945). ASEAN (1967). OIC: 57 negara Islam (1969). NAM: 120 negara membangun.', NULL, NULL),
(1002, NULL, 'hint', 'Susun dari tahun terkecil: 1931, 1945, 1967 dan 1969.', 'Pertubuhan antarabangsa: Komanwel (bekas tanah jajahan British; dibentuk 11 Disember 1931), PBB (terbuka kepada semua negara; ditubuhkan 24 Oktober 1945), OIC (57 negara Islam; ditubuhkan 25 September 1969), NAM (120 negara membangun di Asia, Afrika dan Amerika Selatan). ASEAN ditubuhkan 8 Ogos 1967.', 'Betul! Empat pertubuhan tersusun dan bilik mesyuarat bertepuk tangan.'),
(NULL, 'e10_n1_s3', 'hint', 'ASEAN: 8 Ogos 1967; 10 negara; Jakarta. Sumbangan Malaysia: Mesyuarat Menteri Luar, Kemboja, Selatan Filipina, ZOPFAN, SEAMEO.', NULL, NULL),
(1003, NULL, 'hint', 'Ibu pejabat ASEAN berada di bandar utama Indonesia.', 'ASEAN: ditubuhkan 8 Ogos 1967; 10 negara Asia Tenggara; ibu pejabat di Jakarta, Indonesia. Matlamat: keamanan/kestabilan politik, pertumbuhan ekonomi/sosial/budaya, latihan/penyelidikan, meningkatkan taraf hidup. Sumbangan Malaysia: tuan rumah Mesyuarat Menteri Luar ASEAN, isu Vietnam di Kemboja, konflik Selatan Filipina, ZOPFAN, SEAMEO.', 'Betul! Dokumen jelas semula dan delegasi bertepuk tangan.'),
(NULL, 'e10_n1_s4', 'hint', 'Komanwel: 11 Dis 1931; 54 negara; London; Aparteid; CHOGM 1989; Deklarasi Langkawi. OIC: 25 Sep 1969; 57 negara; Jeddah; Tunku SG pertama; Bank Pembangunan Islam; Bosnia 1991; Palestin; UIAM 1983; 1974 dan 2003.', NULL, NULL),
(1004, NULL, 'hint', 'Komanwel di London, OIC di Jeddah. CHOGM 1989.', 'Komanwel: 11 Disember 1931; 54 negara bekas jajahan British; London. Sumbangan Malaysia: Aparteid, CHOGM 1989, Deklarasi Langkawi 1989 untuk alam sekitar. OIC: 25 September 1969; 57 negara; Jeddah; Tunku Abdul Rahman Setiausaha Agung pertama. Sumbangan Malaysia: Bank Pembangunan Islam, Bosnia dan Herzegovina 1991, Palestin, UIAM 1983, Persidangan OIC 1974 dan 2003.', 'Betul! Delegasi mencatat maklumat dengan tepat dan tersenyum puas.'),
(NULL, 'e10_n1_s5', 'hint', 'PBB: 24 Okt 1945; New York. Malaysia: Palestin, dadah, pasukan pengaman, pendidikan; sijil dan pingat PBB; Razali Ismail; Mazlan Othman.', NULL, NULL),
(1005, NULL, 'hint', 'Cari dewan sidang, bendera, peta pasukan pengaman dan skrin utama.', 'PBB: ditubuhkan 24 Oktober 1945; ibu pejabat New York, AS. Sumbangan Malaysia: isu rakyat Palestin, memerangi dadah, pasukan pengaman, peningkatan mutu pendidikan. Pengiktirafan: sijil dan pingat perkhidmatan PBB; Tan Sri Razali Ismail (Majlis Keselamatan 1989-1990; Perhimpunan Agung sesi ke-51, 1996-1997); Datuk Dr. Mazlan Othman (Angkasa Lepas 1999-2002, 2007).', 'Hebat! Empat bukti ditemui dan dewan sidang bergema dengan tepukan.'),
(NULL, 'e10_n1_s6', 'hint', 'Alam semula jadi 2000: Mulu, Kinabalu. Kebudayaan: Melaka dan George Town 2008, Lenggong 2012. Memori Dunia dan Warisan Budaya Tidak Ketara.', NULL, NULL),
(1006, NULL, 'hint', 'Alam semula jadi 2000, Melaka dan George Town 2008, Lenggong 2012.', 'UNESCO Tapak Warisan Dunia (alam semula jadi, 2000): Taman Negara Gunung Mulu (Sarawak), Taman Kinabalu (Sabah). Kebudayaan: Melaka dan George Town (2008), Warisan Arkeologi Lembah Lenggong (2012). Daftar Memori Dunia: Hikayat Hang Tuah (2001), Surat-menyurat Sultan Kedah (2001), Sulalatus Salatin (2002), Batu Bersurat Terengganu (2009). Warisan Budaya Tidak Ketara: Makyung (2005), Dondang Sayang (2018), Silat (2019), Wangkang (2020).', 'Betul! Pelawat mencatat tahun dengan tepat dan kotak kaca bersinar lebih terang.'),
(NULL, 'e10_n2_s1', 'hint', 'SEAFET dan ASA: Tanah Melayu, Thailand, Filipina. ASEAN: Malaysia, Indonesia, Thailand, Filipina, Singapura.', NULL, NULL),
(1007, NULL, 'hint', 'SEAFET dan ASA: tiga negara. ASEAN: lima negara dengan Indonesia dan Singapura.', 'Pertubuhan serantau: SEAFET (Southeast Asia Friendship and Economic Treaty; Tanah Melayu, Thailand, Filipina), ASA (Association of Southeast Asia; Tanah Melayu, Thailand, Filipina) dan ASEAN (Association of Southeast Asian Nations; Malaysia, Indonesia, Thailand, Filipina, Singapura).', 'Betul! Wakil mencatat anggota dengan tepat dan sidang pun bermula.'),
(NULL, 'e10_n2_s2', 'hint', 'Komanwel: bekas tanah jajahan British. PBB: terbuka kepada semua negara. OIC: 57 negara Islam. NAM: 120 negara membangun di Asia, Afrika dan Amerika Selatan.', NULL, NULL),
(1008, NULL, 'hint', 'Empat pertubuhan: Komanwel, PBB, OIC dan NAM.', 'Pertubuhan antarabangsa: Komanwel (bekas tanah jajahan British; dibentuk 11 Disember 1931), PBB (terbuka kepada semua negara; ditubuhkan 24 Oktober 1945), OIC (57 negara Islam; ditubuhkan 25 September 1969), NAM (120 negara membangun di Asia, Afrika dan Amerika Selatan). ASEAN ditubuhkan 8 Ogos 1967.', 'Betul! Empat pertubuhan bertemu keahliannya dan pintu pun terbuka.'),
(NULL, 'e10_n2_s3', 'hint', 'ASEAN: 8 Ogos 1967; 10 negara; Jakarta. Sumbangan Malaysia: Mesyuarat Menteri Luar, Kemboja, Selatan Filipina, ZOPFAN, SEAMEO.', NULL, NULL),
(1009, NULL, 'hint', 'Cari bendera Malaysia, peta Asia Tenggara, bendera Singapura dan dokumen perjanjian.', 'ASEAN: ditubuhkan 8 Ogos 1967; 10 negara Asia Tenggara; ibu pejabat di Jakarta, Indonesia. Matlamat: keamanan/kestabilan politik, pertumbuhan ekonomi/sosial/budaya, latihan/penyelidikan, meningkatkan taraf hidup. Sumbangan Malaysia: tuan rumah Mesyuarat Menteri Luar ASEAN, isu Vietnam di Kemboja, konflik Selatan Filipina, ZOPFAN, SEAMEO.', 'Hebat! Empat bukti ditemui dan pakar ekonomi mengangguk puas.'),
(NULL, 'e10_n2_s4', 'hint', 'Komanwel: 11 Dis 1931; 54 negara; London; Aparteid; CHOGM 1989; Deklarasi Langkawi. OIC: 25 Sep 1969; 57 negara; Jeddah; Tunku; Bank Pembangunan Islam; Bosnia 1991; Palestin; UIAM 1983; 1974 dan 2003.', NULL, NULL),
(1010, NULL, 'hint', 'Ibu pejabat OIC berada di Arab Saudi.', 'Komanwel: 11 Disember 1931; 54 negara bekas jajahan British; London. Sumbangan Malaysia: Aparteid, CHOGM 1989, Deklarasi Langkawi 1989 untuk alam sekitar. OIC: 25 September 1969; 57 negara; Jeddah; Tunku Abdul Rahman Setiausaha Agung pertama. Sumbangan Malaysia: Bank Pembangunan Islam, Bosnia dan Herzegovina 1991, Palestin, UIAM 1983, Persidangan OIC 1974 dan 2003.', 'Betul! Catatan jelas semula dan utusan melangkah masuk.'),
(NULL, 'e10_n2_s5', 'hint', 'PBB: 24 Okt 1945; New York. Malaysia: Palestin, dadah, pasukan pengaman, pendidikan; sijil dan pingat; Razali Ismail; Mazlan Othman.', NULL, NULL),
(1011, NULL, 'hint', 'PBB di New York; pasukan pengaman menerima sijil dan pingat.', 'PBB: ditubuhkan 24 Oktober 1945; ibu pejabat New York, AS. Sumbangan Malaysia: isu rakyat Palestin, memerangi dadah, pasukan pengaman, peningkatan mutu pendidikan. Pengiktirafan: sijil dan pingat perkhidmatan PBB; Tan Sri Razali Ismail (Majlis Keselamatan 1989-1990; Perhimpunan Agung sesi ke-51, 1996-1997); Datuk Dr. Mazlan Othman (Angkasa Lepas 1999-2002, 2007).', 'Betul! Rekrut mencatat dengan tepat dan memberi tabik hormat.'),
(NULL, 'e10_n2_s6', 'hint', 'Alam semula jadi 2000; Makyung 2005; Melaka dan George Town 2008; Lenggong 2012; Silat 2019. Memori Dunia: 2001, 2002, 2009.', NULL, NULL),
(1012, NULL, 'hint', 'Susun dari tahun terkecil: 2000, 2005, 2008, 2012 dan 2019.', 'UNESCO Tapak Warisan Dunia (alam semula jadi, 2000): Taman Negara Gunung Mulu (Sarawak), Taman Kinabalu (Sabah). Kebudayaan: Melaka dan George Town (2008), Warisan Arkeologi Lembah Lenggong (2012). Daftar Memori Dunia: Hikayat Hang Tuah (2001), Surat-menyurat Sultan Kedah (2001), Sulalatus Salatin (2002), Batu Bersurat Terengganu (2009). Warisan Budaya Tidak Ketara: Makyung (2005), Dondang Sayang (2018), Silat (2019), Wangkang (2020).', 'Betul! Lima pengiktirafan tersusun dan kotak kaca bersinar terang.'),
(NULL, 'e10_n3_s1', 'hint', 'SEAFET dan ASA: Tanah Melayu, Thailand, Filipina. ASEAN: Malaysia, Indonesia, Thailand, Filipina, Singapura.', NULL, NULL),
(1013, NULL, 'hint', 'Negara itu ialah negara kepulauan yang bersama Tanah Melayu dan Thailand.', 'Pertubuhan serantau: SEAFET (Southeast Asia Friendship and Economic Treaty; Tanah Melayu, Thailand, Filipina), ASA (Association of Southeast Asia; Tanah Melayu, Thailand, Filipina) dan ASEAN (Association of Southeast Asian Nations; Malaysia, Indonesia, Thailand, Filipina, Singapura).', 'Betul! Papan nama jelas semula dan pelawat bertepuk tangan.'),
(NULL, 'e10_n3_s2', 'hint', 'Komanwel: bekas tanah jajahan British. PBB: terbuka kepada semua negara. OIC: 57 negara Islam. NAM: 120 negara membangun.', NULL, NULL),
(1014, NULL, 'hint', 'Komanwel bekas jajahan, PBB semua negara, OIC 57, NAM 120.', 'Pertubuhan antarabangsa: Komanwel (bekas tanah jajahan British; dibentuk 11 Disember 1931), PBB (terbuka kepada semua negara; ditubuhkan 24 Oktober 1945), OIC (57 negara Islam; ditubuhkan 25 September 1969), NAM (120 negara membangun di Asia, Afrika dan Amerika Selatan). ASEAN ditubuhkan 8 Ogos 1967.', 'Betul! Pelawat mencatat dengan tepat dan tersenyum puas.'),
(NULL, 'e10_n3_s3', 'hint', 'ASEAN: 8 Ogos 1967; 10 negara; Jakarta. Sumbangan Malaysia: Mesyuarat Menteri Luar, Kemboja, Selatan Filipina, ZOPFAN, SEAMEO.', NULL, NULL),
(1015, NULL, 'hint', 'Lima kad: tarikh, ibu pejabat, bilangan anggota, ZOPFAN dan SEAMEO.', 'ASEAN: ditubuhkan 8 Ogos 1967; 10 negara Asia Tenggara; ibu pejabat di Jakarta, Indonesia. Matlamat: keamanan/kestabilan politik, pertumbuhan ekonomi/sosial/budaya, latihan/penyelidikan, meningkatkan taraf hidup. Sumbangan Malaysia: tuan rumah Mesyuarat Menteri Luar ASEAN, isu Vietnam di Kemboja, konflik Selatan Filipina, ZOPFAN, SEAMEO.', 'Betul! Lima kad bertemu jawapannya dan pelawat bertepuk tangan.'),
(NULL, 'e10_n3_s4', 'hint', 'Komanwel: 11 Dis 1931; 54 negara; London; Aparteid; CHOGM 1989; Deklarasi Langkawi. OIC: 1969; 57 negara; Jeddah; Tunku; Bank Pembangunan Islam; Bosnia 1991; Palestin; UIAM 1983; 1974 dan 2003.', NULL, NULL),
(1016, NULL, 'hint', 'Susun dari tahun terkecil: 1969, 1974, 1983, 1989, 1991 dan 2003.', 'Komanwel: 11 Disember 1931; 54 negara bekas jajahan British; London. Sumbangan Malaysia: Aparteid, CHOGM 1989, Deklarasi Langkawi 1989 untuk alam sekitar. OIC: 25 September 1969; 57 negara; Jeddah; Tunku Abdul Rahman Setiausaha Agung pertama. Sumbangan Malaysia: Bank Pembangunan Islam, Bosnia dan Herzegovina 1991, Palestin, UIAM 1983, Persidangan OIC 1974 dan 2003.', 'Betul! Enam peristiwa tersusun dan bilik mesyuarat bergema dengan tepukan.'),
(NULL, 'e10_n3_s5', 'hint', 'PBB: 24 Okt 1945; New York. Malaysia: Palestin, dadah, pasukan pengaman, pendidikan; sijil dan pingat; Razali Ismail (1989-1990, sesi ke-51); Mazlan Othman.', NULL, NULL),
(1017, NULL, 'hint', 'Beliau juga Pengerusi Perhimpunan Agung PBB sesi ke-51.', 'PBB: ditubuhkan 24 Oktober 1945; ibu pejabat New York, AS. Sumbangan Malaysia: isu rakyat Palestin, memerangi dadah, pasukan pengaman, peningkatan mutu pendidikan. Pengiktirafan: sijil dan pingat perkhidmatan PBB; Tan Sri Razali Ismail (Majlis Keselamatan 1989-1990; Perhimpunan Agung sesi ke-51, 1996-1997); Datuk Dr. Mazlan Othman (Angkasa Lepas 1999-2002, 2007).', 'Betul! Sijil jelas semula dan dewan bergema dengan tepukan.'),
(NULL, 'e10_n3_s6', 'hint', 'Alam semula jadi 2000: Mulu, Kinabalu. Kebudayaan: Melaka dan George Town 2008, Lenggong 2012. Memori Dunia dan Warisan Budaya Tidak Ketara.', NULL, NULL),
(1018, NULL, 'hint', 'Cari gunung, gua, peta bandar dan hologram tengah.', 'UNESCO Tapak Warisan Dunia (alam semula jadi, 2000): Taman Negara Gunung Mulu (Sarawak), Taman Kinabalu (Sabah). Kebudayaan: Melaka dan George Town (2008), Warisan Arkeologi Lembah Lenggong (2012). Daftar Memori Dunia: Hikayat Hang Tuah (2001), Surat-menyurat Sultan Kedah (2001), Sulalatus Salatin (2002), Batu Bersurat Terengganu (2009). Warisan Budaya Tidak Ketara: Makyung (2005), Dondang Sayang (2018), Silat (2019), Wangkang (2020).', 'Hebat! Empat bukti ditemui dan kotak kaca bersinar terang.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(221, 1001, NULL, 'Menjadi wakil muda bukan sekadar duduk di kerusi, {nama}. Kita membawa suara negara ke meja rundingan. Terima kasih kerana menemani aku sepanjang sidang ini!', 1),
(221, 1001, NULL, 'Malaysia berperanan aktif dalam hubungan antarabangsa melalui ASEAN, Komanwel, OIC dan PBB. Kerjasama dan perdamaian membawa kebaikan kepada semua.', 2),
(221, 1001, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wakil muda yang membawa fail penuh nota ke sidang serantau. Pintu bilik mesyuarat dibuka, bendera-bendera berkibar! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(224, 1001, 'e10_n1_s1', 'Wakil muda, selamat tiba di bilik sidang serantau! Hari ini kita menjejak bagaimana negara-negara rantau ini berhimpun.', 1),
(224, 1001, 'e10_n1_s1', 'Pertubuhan pertama: SEAFET, Southeast Asia Friendship and Economic Treaty. Anggotanya Tanah Melayu, Thailand dan Filipina.', 2),
(224, 1001, 'e10_n1_s1', 'Pertubuhan kedua: ASA, Association of Southeast Asia. Anggotanya sama: Tanah Melayu, Thailand dan Filipina!', 3),
(NULL, 1001, 'e10_n1_s1', 'Dua pertubuhan, tiga negara yang sama! Jadi yang ketiga lebih besar?', 4),
(231, 1001, 'e10_n1_s1', 'Betul! ASEAN, Association of Southeast Asian Nations. Anggotanya Malaysia, Indonesia, Thailand, Filipina dan Singapura. Aku wakil Indonesia!', 5),
(231, 1001, 'e10_n1_s1', 'Soalan aku sebelum kau memadankan nama: pertubuhan manakah yang anggotanya Malaysia, Indonesia, Thailand, Filipina dan Singapura?', 6),
(226, 1001, 'e10_n1_s2', 'Selamat datang, wakil muda! Aku utusan Komanwel. Keahlian kami terdiri daripada negara bekas tanah jajahan British.', 1),
(225, 1001, 'e10_n1_s2', 'Aku wakil PBB, Pertubuhan Bangsa-Bangsa Bersatu. Keahlian kami terbuka kepada semua negara!', 2),
(227, 1001, 'e10_n1_s2', 'Aku wakil OIC, Pertubuhan Kerjasama Islam. Kami terdiri daripada 57 buah negara Islam.', 3),
(228, 1001, 'e10_n1_s2', 'Aku duta NAM, Pergerakan Negara-negara Berkecuali. Kami 120 buah negara membangun di Asia, Afrika dan Amerika Selatan!', 4),
(NULL, 1001, 'e10_n1_s2', 'Empat pertubuhan antarabangsa dan satu pertubuhan serantau, ASEAN. Aku mahu susun tarikh penubuhannya!', 5),
(227, 1001, 'e10_n1_s2', 'Sebelum menyusun, soalan aku: berapakah bilangan negara Islam dalam OIC?', 6),
(224, 1001, 'e10_n1_s3', 'Wakil muda, inilah ASEAN. Ditubuhkan pada 8 Ogos 1967 dan dianggotai 10 negara Asia Tenggara. Ibu pejabatnya di Jakarta, Indonesia.', 1),
(224, 1001, 'e10_n1_s3', 'Matlamatnya: keamanan dan kestabilan politik, pertumbuhan ekonomi, sosial dan budaya, latihan dan penyelidikan, serta meningkatkan taraf hidup.', 2),
(224, 1001, 'e10_n1_s3', 'Malaysia menjadi tuan rumah Mesyuarat Menteri Luar ASEAN dan membantu isu pencerobohan Vietnam di Kemboja.', 3),
(224, 1001, 'e10_n1_s3', 'Malaysia meredakan konflik di Selatan Filipina, mengutarakan penubuhan ZOPFAN dan menyertai SEAMEO!', 4),
(NULL, 1001, 'e10_n1_s3', 'Banyak sumbangan! Tetapi dokumen ASEAN ini luntur sedikit, tolong nyahkod!', 5),
(224, 1001, 'e10_n1_s3', 'Sebelum nyahkod, soalan aku: apakah kepanjangan ZOPFAN?', 6),
(226, 1001, 'e10_n1_s4', 'Wakil muda, Komanwel dibentuk pada 11 Disember 1931 dan dianggotai 54 negara bekas jajahan British. Ibu pejabatnya di London, England!', 1),
(226, 1001, 'e10_n1_s4', 'Malaysia mengecam dan membantu menamatkan dasar Aparteid, menjadi tuan rumah CHOGM pada 1989 dan mengisytiharkan Deklarasi Langkawi 1989 untuk alam sekitar.', 2),
(227, 1001, 'e10_n1_s4', 'OIC pula ditubuhkan pada 25 September 1969, dianggotai 57 negara dengan ibu pejabat di Jeddah, Arab Saudi.', 3),
(230, 1001, 'e10_n1_s4', 'Beta, Tunku Abdul Rahman, dilantik sebagai Setiausaha Agung OIC yang pertama!', 4),
(227, 1001, 'e10_n1_s4', 'Malaysia membantu menubuhkan Bank Pembangunan Islam, menangani isu Bosnia dan Herzegovina pada 1991, menyokong perjuangan Palestin, dan menubuhkan UIAM pada 1983.', 5),
(227, 1001, 'e10_n1_s4', 'Malaysia juga menjadi tuan rumah Persidangan OIC pada 1974 dan 2003. Soalan aku: universiti manakah yang ditubuhkan pada 1983?', 6),
(225, 1001, 'e10_n1_s5', 'Wakil muda, inilah PBB! Ditubuhkan pada 24 Oktober 1945 dengan ibu pejabat di New York, Amerika Syarikat.', 1),
(225, 1001, 'e10_n1_s5', 'Malaysia membawa isu rakyat Palestin, mendesak usaha memerangi dadah dan menyarankan peningkatan mutu pendidikan.', 2),
(222, 1001, 'e10_n1_s5', 'Aku penjaga keamanan PBB! Malaysia menyertai pasukan pengaman, dan kami diiktiraf melalui sijil dan pingat perkhidmatan PBB!', 3),
(225, 1001, 'e10_n1_s5', 'Tokoh Malaysia pun terkenal: Tan Sri Razali Ismail ialah Pengerusi Majlis Keselamatan PBB (1989-1990) dan Pengerusi Perhimpunan Agung PBB sesi ke-51 (1996-1997).', 4),
(225, 1001, 'e10_n1_s5', 'Datuk Dr. Mazlan Othman pula Pengarah Hal Ehwal Angkasa Lepas PBB (1999-2002 dan 2007). Cari bukti di dewan ini!', 5),
(222, 1001, 'e10_n1_s5', 'Sebelum itu, soalan aku: apakah pengiktirafan PBB kepada pasukan pengaman Malaysia?', 6),
(223, 1001, 'e10_n1_s6', 'Selamat datang ke ruang UNESCO, wakil muda! Warisan Malaysia diiktiraf dunia di sini.', 1),
(223, 1001, 'e10_n1_s6', 'Tapak Warisan Dunia alam semula jadi pada tahun 2000: Taman Negara Gunung Mulu di Sarawak dan Taman Kinabalu di Sabah!', 2),
(223, 1001, 'e10_n1_s6', 'Tapak Warisan Dunia kebudayaan: Melaka dan George Town pada 2008, serta Warisan Arkeologi Lembah Lenggong pada 2012.', 3),
(223, 1001, 'e10_n1_s6', 'Daftar Memori Dunia: Hikayat Hang Tuah (2001), Surat-menyurat Almarhum Sultan Kedah 1882-1943 (2001), Sulalatus Salatin (2002) dan Batu Bersurat Terengganu (2009).', 4),
(223, 1001, 'e10_n1_s6', 'Warisan Budaya Tidak Ketara Kemanusiaan: Makyung (2005), Dondang Sayang (2018), Silat (2019) dan Wangkang (2020).', 5),
(223, 1001, 'e10_n1_s6', 'Soalan penutup aku: pernyataan manakah yang betul tentang warisan dunia Malaysia?', 6),
(222, 1002, NULL, 'Keamanan dunia dijaga bersama, {nama}. Sehelai topi biru tidak bermakna jika tiada rakan yang setia. Terima kasih kerana meronda bersamaku!', 1),
(222, 1002, NULL, 'Malaysia menyumbang kepada keamanan dan kerjasama dunia melalui ASEAN, Komanwel, OIC dan PBB. Pengiktirafan dunia lahir daripada usaha yang berterusan.', 2),
(222, 1002, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga keamanan yang topi birunya sentiasa tegak. Rondaan bermula, pintu bilik mesyuarat dibuka satu persatu! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(224, 1002, 'e10_n2_s1', 'Penjaga keamanan, sidang serantau akan bermula! Tolong jaga pintu, ya. Sementara itu, kau tahu pertubuhan serantau kita?', 1),
(NULL, 1002, 'e10_n2_s1', 'Sedikit-sedikit sahaja. Tolong ceritakan!', 2),
(224, 1002, 'e10_n2_s1', 'SEAFET, Southeast Asia Friendship and Economic Treaty, dan ASA, Association of Southeast Asia. Anggota keduanya ialah Tanah Melayu, Thailand dan Filipina.', 3),
(231, 1002, 'e10_n2_s1', 'Kemudian ASEAN, Association of Southeast Asian Nations! Anggotanya Malaysia, Indonesia, Thailand, Filipina dan Singapura. Aku wakil Indonesia!', 4),
(224, 1002, 'e10_n2_s1', 'Sebelum kau menjawab soalan kuiz sidang, jawab dahulu soalan aku: apakah kepanjangan ASA?', 5),
(NULL, 1002, 'e10_n2_s2', 'Empat pintu, empat pertubuhan antarabangsa! Giliran siapa dahulu?', 1),
(226, 1002, 'e10_n2_s2', 'Aku utusan Komanwel! Keahlian kami terdiri daripada negara bekas tanah jajahan British.', 2),
(225, 1002, 'e10_n2_s2', 'Aku wakil PBB. Keahlian PBB terbuka kepada semua negara, termasuk Malaysia!', 3),
(227, 1002, 'e10_n2_s2', 'Aku wakil OIC, Pertubuhan Kerjasama Islam. Kami terdiri daripada 57 buah negara Islam.', 4),
(228, 1002, 'e10_n2_s2', 'Aku duta NAM. Pergerakan Negara-negara Berkecuali ini terdiri daripada 120 buah negara membangun di Asia, Afrika dan Amerika Selatan!', 5),
(225, 1002, 'e10_n2_s2', 'Sebelum kau memadankan, soalan PBB: pertubuhan manakah yang ditubuhkan pada 24 Oktober 1945?', 6),
(224, 1002, 'e10_n2_s3', 'Penjaga, kau meronda di bilik ASEAN! Ia ditubuhkan pada 8 Ogos 1967 dan dianggotai 10 negara Asia Tenggara. Ibu pejabatnya di Jakarta.', 1),
(224, 1002, 'e10_n2_s3', 'Matlamatnya: keamanan dan kestabilan politik, pertumbuhan ekonomi, sosial dan budaya, latihan dan penyelidikan, serta meningkatkan taraf hidup.', 2),
(NULL, 1002, 'e10_n2_s3', 'Dan apakah sumbangan Malaysia?', 3),
(224, 1002, 'e10_n2_s3', 'Malaysia menjadi tuan rumah Mesyuarat Menteri Luar ASEAN, membantu isu pencerobohan Vietnam di Kemboja dan meredakan konflik di Selatan Filipina.', 4),
(224, 1002, 'e10_n2_s3', 'Malaysia juga mengutarakan penubuhan ZOPFAN dan menyertai SEAMEO! Sebelum kau memeriksa bilik, soalan aku: berapakah negara anggota ASEAN?', 5),
(226, 1002, 'e10_n2_s4', 'Penjaga! Komanwel dibentuk pada 11 Disember 1931 dengan 54 negara bekas jajahan British. Ibu pejabatnya di London, England.', 1),
(226, 1002, 'e10_n2_s4', 'Malaysia mengecam dan membantu menamatkan dasar Aparteid, menjadi tuan rumah CHOGM 1989 dan mengisytiharkan Deklarasi Langkawi 1989 untuk alam sekitar.', 2),
(227, 1002, 'e10_n2_s4', 'OIC ditubuhkan pada 25 September 1969, dengan 57 negara dan ibu pejabat di Jeddah, Arab Saudi.', 3),
(230, 1002, 'e10_n2_s4', 'Beta, Tunku Abdul Rahman, Setiausaha Agung OIC yang pertama!', 4),
(229, 1002, 'e10_n2_s4', 'Aku sukarelawan kemanusiaan OIC. Malaysia membantu menubuhkan Bank Pembangunan Islam, menangani isu Bosnia dan Herzegovina 1991 dan menyokong perjuangan Palestin.', 5),
(229, 1002, 'e10_n2_s4', 'UIAM ditubuhkan pada 1983, dan Malaysia menjadi tuan rumah Persidangan OIC pada 1974 dan 2003! Soalan aku: siapa Setiausaha Agung OIC yang pertama?', 6),
(225, 1002, 'e10_n2_s5', 'Penjaga, kau bertugas di pusat operasi PBB! Ditubuhkan pada 24 Oktober 1945 dengan ibu pejabat di New York, Amerika Syarikat.', 1),
(225, 1002, 'e10_n2_s5', 'Malaysia membawa isu rakyat Palestin, mendesak usaha memerangi dadah, menyertai pasukan pengaman dan menyarankan peningkatan mutu pendidikan.', 2),
(NULL, 1002, 'e10_n2_s5', 'Pasukan pengaman diiktiraf, bukan?', 3),
(225, 1002, 'e10_n2_s5', 'Betul! Melalui pemberian sijil dan pingat perkhidmatan PBB. Tokoh Malaysia pun diiktiraf: Tan Sri Razali Ismail, Pengerusi Majlis Keselamatan PBB (1989-1990).', 4),
(225, 1002, 'e10_n2_s5', 'Beliau juga Pengerusi Perhimpunan Agung PBB sesi ke-51 (1996-1997), dan Datuk Dr. Mazlan Othman Pengarah Hal Ehwal Angkasa Lepas PBB (1999-2002 dan 2007).', 5),
(225, 1002, 'e10_n2_s5', 'Soalan aku sebelum kuiz: siapakah Pengarah Hal Ehwal Angkasa Lepas PBB itu?', 6),
(223, 1002, 'e10_n2_s6', 'Penjaga, rondaan terakhir! Ruang UNESCO menyimpan warisan Malaysia yang diiktiraf dunia.', 1),
(223, 1002, 'e10_n2_s6', 'Tapak Warisan Dunia alam semula jadi pada 2000: Taman Negara Gunung Mulu di Sarawak dan Taman Kinabalu di Sabah.', 2),
(223, 1002, 'e10_n2_s6', 'Kebudayaan: Melaka dan George Town pada 2008, dan Warisan Arkeologi Lembah Lenggong pada 2012.', 3),
(223, 1002, 'e10_n2_s6', 'Daftar Memori Dunia: Hikayat Hang Tuah dan Surat-menyurat Almarhum Sultan Kedah 1882-1943 (2001), Sulalatus Salatin (2002) dan Batu Bersurat Terengganu (2009).', 4),
(223, 1002, 'e10_n2_s6', 'Warisan Budaya Tidak Ketara Kemanusiaan: Makyung (2005), Dondang Sayang (2018), Silat (2019) dan Wangkang (2020).', 5),
(NULL, 1002, 'e10_n2_s6', 'Senarai yang panjang! Tolong susun lima tahun pengiktirafan ini supaya mudah dihafal.', 6),
(223, 1002, 'e10_n2_s6', 'Sebelum menyusun, soalan aku: Batu Bersurat Terengganu masuk Daftar Memori Dunia pada tahun berapa?', 7),
(223, 1003, NULL, 'Pameran hanya hidup jika ada yang menceritakannya, {nama}. Hari ini kau menjadi suara yang membawa kisah Malaysia kepada dunia. Terima kasih kerana membantuku memandu!', 1),
(223, 1003, NULL, 'Malaysia berperanan aktif dalam ASEAN, Komanwel, OIC dan PBB, dan warisannya diiktiraf dunia. Kisah ini patut diceritakan dengan bangga kepada semua.', 2),
(223, 1003, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemandu pameran yang kad namanya berkilat di dada. Pelawat sudah beratur di pintu masuk, lawatan bermula! Lihat dengan matanya dan bercakaplah dengan suaranya.', 3),
(NULL, 1003, 'e10_n3_s1', 'Selamat datang, para pelawat! Bilik pertama ialah pertubuhan serantau. Pakar, tolong bantu!', 1),
(224, 1003, 'e10_n3_s1', 'Dengan senang hati! SEAFET ialah Southeast Asia Friendship and Economic Treaty, dan ASA ialah Association of Southeast Asia.', 2),
(224, 1003, 'e10_n3_s1', 'Anggota keduanya sama: Tanah Melayu, Thailand dan Filipina.', 3),
(231, 1003, 'e10_n3_s1', 'Aku wakil Indonesia! ASEAN pula Association of Southeast Asian Nations, dianggotai Malaysia, Indonesia, Thailand, Filipina dan Singapura.', 4),
(NULL, 1003, 'e10_n3_s1', 'Papan nama anggota SEAFET ini luntur sedikit. Tolong nyahkod bersama kami!', 5),
(231, 1003, 'e10_n3_s1', 'Soalan aku dahulu: apakah kepanjangan ASEAN?', 6),
(NULL, 1003, 'e10_n3_s2', 'Bilik kedua: pertubuhan antarabangsa! Utusan sekalian, silakan memperkenalkan diri.', 1),
(226, 1003, 'e10_n3_s2', 'Aku utusan Komanwel. Ahlinya terdiri daripada negara bekas tanah jajahan British.', 2),
(225, 1003, 'e10_n3_s2', 'Aku wakil PBB. Keahlian PBB terbuka kepada semua negara!', 3),
(227, 1003, 'e10_n3_s2', 'Aku wakil OIC. Pertubuhan Kerjasama Islam terdiri daripada 57 buah negara Islam.', 4),
(228, 1003, 'e10_n3_s2', 'Aku duta NAM. Kami 120 buah negara membangun di Asia, Afrika dan Amerika Selatan!', 5),
(228, 1003, 'e10_n3_s2', 'Soalan aku: berapakah bilangan negara membangun dalam NAM?', 6),
(224, 1003, 'e10_n3_s3', 'Pemandu, bilik ini bilik ASEAN! Ia ditubuhkan pada 8 Ogos 1967, dianggotai 10 negara Asia Tenggara dan beribu pejabat di Jakarta.', 1),
(224, 1003, 'e10_n3_s3', 'Matlamatnya: keamanan dan kestabilan politik, pertumbuhan ekonomi, sosial dan budaya, latihan dan penyelidikan, serta meningkatkan taraf hidup.', 2),
(NULL, 1003, 'e10_n3_s3', 'Pelawat sekalian, dan apakah sumbangan Malaysia?', 3),
(224, 1003, 'e10_n3_s3', 'Malaysia menjadi tuan rumah Mesyuarat Menteri Luar ASEAN, membantu isu pencerobohan Vietnam di Kemboja dan meredakan konflik di Selatan Filipina.', 4),
(224, 1003, 'e10_n3_s3', 'Malaysia juga mengutarakan penubuhan ZOPFAN dan menyertai SEAMEO! Sekarang padankan butiran ASEAN pada kad pameran ini.', 5),
(226, 1003, 'e10_n3_s4', 'Pemandu, Komanwel dibentuk pada 11 Disember 1931 dan dianggotai 54 negara bekas jajahan British. Ibu pejabatnya di London, England.', 1),
(226, 1003, 'e10_n3_s4', 'Malaysia mengecam dan membantu menamatkan dasar Aparteid. Malaysia juga tuan rumah CHOGM 1989 dan mengisytiharkan Deklarasi Langkawi 1989 untuk alam sekitar.', 2),
(227, 1003, 'e10_n3_s4', 'OIC ditubuhkan pada 25 September 1969, dianggotai 57 negara dengan ibu pejabat di Jeddah, Arab Saudi.', 3),
(230, 1003, 'e10_n3_s4', 'Beta, Tunku Abdul Rahman, dilantik sebagai Setiausaha Agung OIC yang pertama.', 4),
(227, 1003, 'e10_n3_s4', 'Malaysia membantu menubuhkan Bank Pembangunan Islam, menangani isu Bosnia dan Herzegovina 1991, menyokong perjuangan Palestin dan menubuhkan UIAM pada 1983.', 5),
(227, 1003, 'e10_n3_s4', 'Malaysia menjadi tuan rumah Persidangan OIC pada 1974 dan 2003. Soalan aku: siapa Setiausaha Agung OIC yang pertama?', 6),
(225, 1003, 'e10_n3_s5', 'Pemandu, dewan ini milik PBB! Ditubuhkan pada 24 Oktober 1945 dengan ibu pejabat di New York, Amerika Syarikat.', 1),
(225, 1003, 'e10_n3_s5', 'Malaysia membawa isu rakyat Palestin, mendesak usaha memerangi dadah dan menyarankan peningkatan mutu pendidikan.', 2),
(222, 1003, 'e10_n3_s5', 'Aku penjaga keamanan PBB! Malaysia menyertai pasukan pengaman dan diiktiraf melalui sijil dan pingat perkhidmatan PBB!', 3),
(225, 1003, 'e10_n3_s5', 'Tan Sri Razali Ismail ialah Pengerusi Majlis Keselamatan PBB (1989-1990) dan Pengerusi Perhimpunan Agung PBB sesi ke-51 (1996-1997).', 4),
(225, 1003, 'e10_n3_s5', 'Datuk Dr. Mazlan Othman ialah Pengarah Hal Ehwal Angkasa Lepas PBB (1999-2002 dan 2007).', 5),
(NULL, 1003, 'e10_n3_s5', 'Wah, bangga! Tetapi sijil ini luntur sedikit. Tolong nyahkod!', 6),
(222, 1003, 'e10_n3_s5', 'Sebelum nyahkod, soalan aku: apakah sumbangan Malaysia dalam bidang keamanan PBB?', 7),
(223, 1003, 'e10_n3_s6', 'Pemandu, bilik terakhir! Di sini warisan Malaysia diiktiraf UNESCO.', 1),
(223, 1003, 'e10_n3_s6', 'Tapak Warisan Dunia alam semula jadi pada 2000: Taman Negara Gunung Mulu di Sarawak dan Taman Kinabalu di Sabah.', 2),
(223, 1003, 'e10_n3_s6', 'Tapak kebudayaan: Melaka dan George Town pada 2008, dan Warisan Arkeologi Lembah Lenggong pada 2012.', 3),
(223, 1003, 'e10_n3_s6', 'Daftar Memori Dunia: Hikayat Hang Tuah dan Surat-menyurat Almarhum Sultan Kedah 1882-1943 (2001), Sulalatus Salatin (2002) dan Batu Bersurat Terengganu (2009).', 4),
(223, 1003, 'e10_n3_s6', 'Warisan Budaya Tidak Ketara Kemanusiaan: Makyung (2005), Dondang Sayang (2018), Silat (2019) dan Wangkang (2020).', 5),
(NULL, 1003, 'e10_n3_s6', 'Banyak bukti kebanggaan! Mari kita cari buktinya di dalam kotak kaca ini.', 6),
(223, 1003, 'e10_n3_s6', 'Sebelum itu, soalan aku: Taman Kinabalu terletak di negeri mana?', 7);
INSERT INTO QuestionBank (bankID, eraID) VALUES (10, 10)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(1001, 10, 'Apakah kepanjangan SEAFET?', 'Southeast Asia Federation and Economic Treaty', 'Southeast Asian Friendship and Education Treaty', 'Southeast Asia Friendship and Economic Treaty', 'South Eastern Alliance for Economic Trade', 'C', 'Nama itu mengandungi perkataan persahabatan dan ekonomi.', 'SEAFET ialah Southeast Asia Friendship and Economic Treaty, pertubuhan serantau yang disertai Tanah Melayu, Thailand dan Filipina.'),
(1002, 10, 'Negara manakah anggota SEAFET dan ASA?', 'Tanah Melayu, Indonesia dan Singapura', 'Thailand, Filipina dan Singapura', 'Indonesia, Thailand dan Singapura', 'Tanah Melayu, Thailand dan Filipina', 'D', 'Tiga negara itu sama bagi kedua-dua pertubuhan.', 'SEAFET dan ASA masing-masing dianggotai oleh Tanah Melayu, Thailand dan Filipina.'),
(1003, 10, 'Apakah kepanjangan ASA?', 'Alliance of Southeast Asian States', 'Association of South Asian Allies', 'Association of Southeast Asia', 'Assembly of Southeast Asian Authorities', 'C', 'Huruf pertamanya ialah Association.', 'ASA ialah Association of Southeast Asia, pertubuhan serantau yang disertai Tanah Melayu, Thailand dan Filipina.'),
(1004, 10, 'Negara manakah termasuk dalam keahlian ASEAN yang awal selain Malaysia?', 'Vietnam, Kemboja, Laos dan Myanmar', 'Jepun, China, Korea dan India', 'Indonesia, Thailand, Filipina dan Singapura', 'Indonesia, Australia, Jepun dan Singapura', 'C', 'Empat negara itu bersama Malaysia dalam senarai pertubuhan ini.', 'ASEAN dianggotai oleh Malaysia, Indonesia, Thailand, Filipina dan Singapura.'),
(1005, 10, 'Apakah kepanjangan ASEAN?', 'Alliance of Southeast Asian National States', 'Association of Southeast Asia Navies', 'Assembly of Southeast Asian Neighbours', 'Association of Southeast Asian Nations', 'D', 'Perkataan terakhirnya ialah Nations.', 'ASEAN ialah Association of Southeast Asian Nations.'),
(1006, 10, 'Antara berikut, yang manakah pertubuhan serantau?', 'PBB', 'Komanwel', 'NAM', 'ASEAN', 'D', 'Serantau bermaksud satu rantau, iaitu Asia Tenggara.', 'ASEAN ialah pertubuhan serantau, manakala PBB, Komanwel dan NAM ialah pertubuhan antarabangsa.'),
(1007, 10, 'Siapakah yang layak menjadi ahli Komanwel?', 'Negara bekas tanah jajahan British', 'Semua negara di Asia Tenggara', 'Hanya negara Islam', 'Hanya negara membangun di Afrika', 'A', 'Sejarah pentadbiran British menjadi asas keahlian.', 'Keahlian Komanwel terdiri daripada negara bekas tanah jajahan British.'),
(1008, 10, 'Apakah kepanjangan PBB?', 'Pertubuhan Bangsa-Bangsa Bersatu', 'Pergerakan Bangsa-Bangsa Berkecuali', 'Perhimpunan Bangsa-Bangsa Besar', 'Pertubuhan Belia Bersatu Bangsa', 'A', 'Ia ialah pertubuhan yang bersatu untuk semua bangsa.', 'PBB ialah Pertubuhan Bangsa-Bangsa Bersatu, yang keahliannya terbuka kepada semua negara.'),
(1009, 10, 'Berapakah bilangan negara Islam dalam OIC?', '120 buah negara', '57 buah negara', '54 buah negara', '10 buah negara', 'B', 'Bilangan itu lebih daripada lima puluh dan kurang daripada enam puluh.', 'OIC, iaitu Pertubuhan Kerjasama Islam, terdiri daripada 57 buah negara Islam.'),
(1010, 10, 'Apakah kepanjangan NAM?', 'Pertubuhan Negara-negara Asia Muda', 'Persatuan Negara-negara Antarabangsa Malaysia', 'Pergerakan Negara-negara Asia Merdeka', 'Pergerakan Negara-negara Berkecuali', 'D', 'Ia berkaitan dengan sikap tidak memihak kepada mana-mana blok.', 'NAM ialah Pergerakan Negara-negara Berkecuali.'),
(1011, 10, 'Berapakah bilangan negara membangun dalam NAM?', '57 buah negara', '120 buah negara', '54 buah negara', '10 buah negara', 'B', 'Negaranya terdiri daripada Asia, Afrika dan Amerika Selatan.', 'NAM dianggotai 120 buah negara membangun di Asia, Afrika dan Amerika Selatan.'),
(1012, 10, 'Pertubuhan manakah yang keahliannya terbuka kepada semua negara?', 'PBB', 'Komanwel', 'OIC', 'ASEAN', 'A', 'Pertubuhan ini bertapak di New York.', 'Keahlian PBB terbuka kepada semua negara.'),
(1013, 10, 'Bilakah ASEAN ditubuhkan?', '11 Disember 1931', '8 Ogos 1967', '25 September 1969', '24 Oktober 1945', 'B', 'Tarikh itu pada bulan Ogos.', 'ASEAN ditubuhkan pada 8 Ogos 1967.'),
(1014, 10, 'Berapakah bilangan negara anggota ASEAN kini?', '10 negara Asia Tenggara', '5 negara Asia Tenggara', '57 negara Islam', '54 negara bekas jajahan', 'A', 'Bilangannya tepat sepuluh.', 'ASEAN dianggotai 10 negara Asia Tenggara.'),
(1015, 10, 'Di manakah ibu pejabat ASEAN?', 'Kuala Lumpur, Malaysia', 'Jakarta, Indonesia', 'Bangkok, Thailand', 'New York, Amerika Syarikat', 'B', 'Ia terletak di sebuah negara Asia Tenggara yang besar.', 'Ibu pejabat ASEAN terletak di Jakarta, Indonesia.'),
(1016, 10, 'Antara berikut, yang manakah matlamat ASEAN?', 'Menjadikan semua anggota negara Islam', 'Menyatukan semua negara bekas jajahan', 'Memelihara keamanan dan kestabilan politik', 'Menamatkan dasar Aparteid sahaja', 'C', 'Matlamat itu berkaitan politik serantau.', 'Matlamat ASEAN termasuk keamanan dan kestabilan politik, pertumbuhan ekonomi, sosial dan budaya.'),
(1017, 10, 'Apakah satu matlamat ASEAN selain keamanan dan kestabilan politik?', 'Mengisytiharkan deklarasi alam sekitar', 'Meningkatkan taraf hidup rakyat', 'Menubuhkan sebuah bank Islam', 'Menghantar angkasawan ke angkasa', 'B', 'Ia berkaitan dengan kehidupan rakyat.', 'ASEAN juga bermatlamat meningkatkan taraf hidup rakyat serta menggalakkan latihan dan penyelidikan.'),
(1018, 10, 'Apakah sumbangan Malaysia kepada ASEAN berkaitan Vietnam?', 'Membantu Vietnam menjadi anggota Komanwel', 'Menubuhkan Bank Pembangunan Islam di Vietnam', 'Membantu isu pencerobohan Vietnam di Kemboja', 'Menghantar pasukan pengaman ke Vietnam', 'C', 'Isu itu berlaku di sebuah negara jiran Vietnam.', 'Malaysia membantu menangani isu pencerobohan Vietnam di Kemboja.'),
(1019, 10, 'Konflik manakah yang diredakan Malaysia dalam ASEAN?', 'Konflik di Utara Thailand', 'Konflik di Selatan Filipina', 'Konflik di Timur Indonesia', 'Konflik di Barat Singapura', 'B', 'Ia berlaku di sebuah negara yang bersempadan laut dengan Sabah.', 'Malaysia membantu meredakan konflik di Selatan Filipina.'),
(1020, 10, 'Apakah kepanjangan ZOPFAN yang diutarakan oleh Malaysia?', 'Zon Anggota Politik Federasi ASEAN', 'Zon Aman, Bebas dan Berkecuali', 'Zon Ahli Pertubuhan Antarabangsa', 'Zon Aman Perdagangan Bebas ASEAN', 'B', 'Namanya mengandungi tiga ciri: aman, bebas dan berkecuali.', 'Malaysia mengutarakan penubuhan ZOPFAN, iaitu Zon Aman, Bebas dan Berkecuali.'),
(1021, 10, 'Organisasi pendidikan manakah yang Malaysia sertai dalam ASEAN?', 'UNESCO', 'SEAFET', 'NAM', 'SEAMEO', 'D', 'Namanya berkaitan dengan menteri pendidikan Asia Tenggara.', 'Malaysia menyertai SEAMEO sebagai sumbangan di peringkat serantau.'),
(1022, 10, 'Apakah peranan Malaysia dalam Mesyuarat Menteri Luar ASEAN?', 'Menjadi pengerusi tetap', 'Menjadi pemerhati', 'Menjadi penaja kewangan tunggal', 'Menjadi tuan rumah', 'D', 'Mesyuarat itu diadakan di Malaysia.', 'Malaysia menjadi tuan rumah Mesyuarat Menteri Luar ASEAN.'),
(1023, 10, 'Bilakah Komanwel dibentuk?', '8 Ogos 1967', '25 September 1969', '11 Disember 1931', '24 Oktober 1945', 'C', 'Ia dibentuk pada tahun 1931.', 'Komanwel dibentuk pada 11 Disember 1931.'),
(1024, 10, 'Berapakah bilangan negara anggota Komanwel?', '57 negara', '54 negara', '120 negara', '10 negara', 'B', 'Bilangannya lebih daripada lima puluh dan kurang daripada lima puluh lima.', 'Komanwel dianggotai 54 negara bekas jajahan British.'),
(1025, 10, 'Di manakah ibu pejabat Komanwel?', 'London, England', 'New York, Amerika Syarikat', 'Jeddah, Arab Saudi', 'Jakarta, Indonesia', 'A', 'Ia terletak di bekas pusat pentadbiran penjajah.', 'Ibu pejabat Komanwel terletak di London, England.'),
(1026, 10, 'Apakah dasar yang dikecam Malaysia dalam Komanwel?', 'Dasar Pandang ke Timur', 'Dasar Ekonomi Baru', 'Dasar Aparteid', 'Dasar Pengimportan Bebas', 'C', 'Dasar itu berkaitan dengan diskriminasi kaum di Afrika Selatan.', 'Malaysia mengecam dan membantu menamatkan dasar Aparteid melalui Komanwel.'),
(1027, 10, 'Pada tahun berapakah Malaysia menjadi tuan rumah CHOGM?', '1931', '1974', '2003', '1989', 'D', 'Tahun itu juga tahun Deklarasi Langkawi.', 'Malaysia menjadi tuan rumah CHOGM pada tahun 1989.'),
(1028, 10, 'Apakah isu yang ditekankan dalam Deklarasi Langkawi 1989?', 'Pendidikan tinggi', 'Alam sekitar', 'Keamanan Palestin', 'Perdagangan bebas serantau', 'B', 'Isu itu berkaitan dengan hutan, laut dan udara.', 'Deklarasi Langkawi 1989 diisytiharkan Malaysia untuk alam sekitar.'),
(1029, 10, 'Bilakah OIC ditubuhkan?', '11 Disember 1931', '25 September 1969', '24 Oktober 1945', '8 Ogos 1967', 'B', 'Ia ditubuhkan pada bulan September.', 'OIC ditubuhkan pada 25 September 1969.'),
(1030, 10, 'Di manakah ibu pejabat OIC?', 'London, England', 'New York, Amerika Syarikat', 'Jakarta, Indonesia', 'Jeddah, Arab Saudi', 'D', 'Bandar itu terletak di Tanah Arab.', 'Ibu pejabat OIC terletak di Jeddah, Arab Saudi.'),
(1031, 10, 'Siapakah Setiausaha Agung OIC yang pertama?', 'Tunku Abdul Rahman', 'Tun Abdul Razak', 'Tun Dr. Mahathir', 'Tun Hussein Onn', 'A', 'Beliau juga Perdana Menteri pertama Malaysia.', 'Tunku Abdul Rahman dilantik sebagai Setiausaha Agung OIC pertama.'),
(1032, 10, 'Apakah institusi kewangan yang Malaysia bantu tubuhkan dalam OIC?', 'Bank Dunia', 'Tabung Kewangan Antarabangsa', 'Bank Pembangunan Asia', 'Bank Pembangunan Islam', 'D', 'Namanya mengandungi perkataan Islam.', 'Malaysia menyumbang kepada penubuhan Bank Pembangunan Islam.'),
(1033, 10, 'Isu manakah yang ditangani Malaysia dalam OIC pada tahun 1991?', 'Isu pencerobohan di Kemboja', 'Isu konflik Selatan Filipina', 'Isu dasar Aparteid Afrika', 'Isu Bosnia dan Herzegovina', 'D', 'Negara itu terletak di Eropah.', 'Malaysia menangani isu Bosnia dan Herzegovina pada tahun 1991.'),
(1034, 10, 'Apakah universiti yang ditubuhkan pada tahun 1983 sebagai sumbangan Malaysia dalam OIC?', 'UiTM', 'UPSI', 'UIAM', 'UTHM', 'C', 'Namanya mengandungi perkataan Islam dan antarabangsa.', 'Universiti Islam Antarabangsa Malaysia (UIAM) ditubuhkan pada tahun 1983.'),
(1035, 10, 'Pada tahun berapakah Malaysia menjadi tuan rumah Persidangan OIC?', '1974 dan 2003', '1931 dan 1945', '1967 dan 1989', '1983 dan 1991', 'A', 'Dua tahun itu mengikut tahun 1970-an dan 2000-an.', 'Malaysia menjadi tuan rumah Persidangan OIC pada tahun 1974 dan 2003.'),
(1036, 10, 'Bilakah PBB ditubuhkan?', '11 Disember 1931', '25 September 1969', '24 Oktober 1945', '8 Ogos 1967', 'C', 'Ia ditubuhkan pada bulan Oktober.', 'PBB ditubuhkan pada 24 Oktober 1945.'),
(1037, 10, 'Di manakah ibu pejabat PBB?', 'New York, Amerika Syarikat', 'London, England', 'Jeddah, Arab Saudi', 'Washington, Amerika Syarikat', 'A', 'Ia terletak di sebuah bandar di Amerika.', 'Ibu pejabat PBB terletak di New York, Amerika Syarikat.'),
(1038, 10, 'Isu rakyat manakah yang dibawa Malaysia ke PBB?', 'Isu rakyat Aparteid', 'Isu rakyat Kemboja', 'Isu rakyat Bosnia sahaja', 'Isu rakyat Palestin', 'D', 'Isu itu juga disokong dalam OIC.', 'Malaysia membawa isu rakyat Palestin ke PBB.'),
(1039, 10, 'Apakah usaha yang didesak Malaysia di PBB?', 'Menaikkan harga minyak', 'Memperluas penjajahan', 'Memerangi dadah', 'Mengehadkan kegiatan sukan', 'C', 'Ia berkaitan dengan masalah sosial yang memudaratkan.', 'Malaysia mendesak usaha memerangi dadah di PBB.'),
(1040, 10, 'Apakah sumbangan Malaysia kepada PBB dalam bidang keamanan?', 'Menyertai pasukan pengaman', 'Menghantar angkasawan', 'Menubuhkan bank dunia', 'Menjadi tuan rumah Olimpik', 'A', 'Anggota pasukan itu memakai topi biru.', 'Malaysia menyertai pasukan pengaman PBB.'),
(1041, 10, 'Bagaimana pasukan pengaman Malaysia diiktiraf oleh PBB?', 'Melalui pemberian sijil dan pingat perkhidmatan PBB', 'Melalui pemberian wang tunai kepada setiap anggota', 'Melalui pemberian tanah di bandar New York', 'Melalui pemberian kerusi tetap di Majlis Keselamatan', 'A', 'Pengiktirafan itu ialah bukti perkhidmatan.', 'Pasukan pengaman Malaysia diiktiraf melalui sijil dan pingat perkhidmatan PBB.'),
(1042, 10, 'Siapakah Pengerusi Majlis Keselamatan PBB pada 1989 hingga 1990?', 'Datuk Dr. Mazlan Othman', 'Tan Sri Razali Ismail', 'Tunku Abdul Rahman', 'Tun Abdul Razak', 'B', 'Beliau kemudian mengerusikan sesi ke-51 Perhimpunan Agung PBB.', 'Tan Sri Razali Ismail ialah Pengerusi Majlis Keselamatan PBB (1989-1990) dan Pengerusi Perhimpunan Agung PBB sesi ke-51 (1996-1997).'),
(1043, 10, 'Siapakah Pengarah Hal Ehwal Angkasa Lepas PBB?', 'Tan Sri Razali Ismail', 'Tunku Abdul Rahman', 'Datuk Dr. Mazlan Othman', 'Tun Dr. Mahathir', 'C', 'Beliau ialah seorang wanita Malaysia.', 'Datuk Dr. Mazlan Othman ialah Pengarah Hal Ehwal Angkasa Lepas PBB pada 1999-2002 dan 2007.'),
(1044, 10, 'Pada tahun berapakah Taman Negara Gunung Mulu dan Taman Kinabalu menjadi Tapak Warisan Dunia UNESCO?', '2000', '2008', '2012', '1989', 'A', 'Tahun itu ialah tahun alam semula jadi.', 'Taman Negara Gunung Mulu (Sarawak) dan Taman Kinabalu (Sabah) menjadi Tapak Warisan Dunia alam semula jadi pada 2000.'),
(1045, 10, 'Taman Kinabalu terletak di negeri mana?', 'Sarawak', 'Sabah', 'Pahang', 'Perak', 'B', 'Gunung tertinggi Malaysia terletak di negeri itu.', 'Taman Kinabalu terletak di Sabah.'),
(1046, 10, 'Apakah dua tapak warisan kebudayaan UNESCO pada tahun 2008?', 'Taman Negara dan Kinabalu', 'Lenggong dan Mulu', 'Kuching dan Kota Kinabalu', 'Melaka dan George Town', 'D', 'Kedua-duanya ialah bandar bersejarah Selat Melaka.', 'Melaka dan George Town menjadi Tapak Warisan Dunia kebudayaan pada 2008.'),
(1047, 10, 'Apakah tapak warisan UNESCO yang diiktiraf pada tahun 2012?', 'Warisan Arkeologi Lembah Lenggong', 'Taman Negara Gunung Mulu di Sarawak', 'Melaka dan George Town di Selat Melaka', 'Taman Kinabalu di negeri Sabah', 'A', 'Tapak itu berkaitan dengan penemuan arkeologi di Perak.', 'Warisan Arkeologi Lembah Lenggong diiktiraf pada 2012.'),
(1048, 10, 'Manakah antara berikut dalam Daftar Memori Dunia pada tahun 2001?', 'Sulalatus Salatin', 'Batu Bersurat Terengganu', 'Hikayat Hang Tuah', 'Warisan Lembah Lenggong', 'C', 'Ia ialah kisah laksamana Melayu.', 'Hikayat Hang Tuah (2001) dan Surat-menyurat Almarhum Sultan Kedah 1882-1943 (2001) dalam Daftar Memori Dunia.'),
(1049, 10, 'Pada tahun berapakah Batu Bersurat Terengganu masuk Daftar Memori Dunia?', '2009', '2001', '2002', '2018', 'A', 'Tahun itu sebelum tahun 2010.', 'Batu Bersurat Terengganu masuk Daftar Memori Dunia pada 2009.'),
(1050, 10, 'Manakah warisan budaya tidak ketara yang diiktiraf pada tahun 2019?', 'Makyung', 'Silat', 'Dondang Sayang', 'Wangkang', 'B', 'Ia ialah seni mempertahankan diri.', 'Silat diiktiraf pada 2019, Makyung pada 2005, Dondang Sayang pada 2018 dan Wangkang pada 2020.');
